/* 統測選擇題：字彙 100、文法 100、情境對話 100，附中文解析。由第二位老師盲解審核。 */
window.MCQ_ITEMS = [{"id": "M001", "type": "vocab", "q": "If you want to return the shoes, you must bring the ______ that shows the date and price of your purchase.", "options": ["license", "receipt", "budget", "menu"], "answer": 1, "explain": "句意：如果你想退還這雙鞋，必須帶著顯示購買日期和價格的收據。receipt 收據，符合「顯示日期與價格」的描述。(A) license 執照 (C) budget 預算 (D) menu 菜單，皆不能證明購買紀錄。故選 (B)。", "level": "B1", "topic": "shopping"}, {"id": "M002", "type": "vocab", "q": "The manager decided to ______ the meeting until next Monday because many staff members were sick.", "options": ["attend", "prevent", "compare", "postpone"], "answer": 3, "explain": "句意：經理決定把會議延到下週一，因為許多員工生病了。postpone 延期，常與 until 連用表示延到某時。(A) attend 參加 (B) prevent 預防 (C) compare 比較，皆無法與 until next Monday 搭配表示延後。故選 (D)。", "level": "B1", "topic": "workplace meetings"}, {"id": "M003", "type": "vocab", "q": "Jenny is very ______; she always tells the truth, even when it gets her into trouble.", "options": ["honest", "jealous", "curious", "nervous"], "answer": 0, "explain": "句意：Jenny 很誠實，即使說實話會讓她惹上麻煩，她仍總是說實話。honest 誠實的。(B) jealous 嫉妒的 (C) curious 好奇的 (D) nervous 緊張的，皆與「總是說實話」無關。故選 (A)。", "level": "B1", "topic": "personality"}, {"id": "M004", "type": "vocab", "q": "Before signing the ______, you should read every page carefully to understand your rights and duties at your new job.", "options": ["complaint", "campaign", "contract", "conflict"], "answer": 2, "explain": "句意：在簽合約之前，你應該仔細閱讀每一頁，了解你在新工作中的權利和義務。contract 合約，可以「簽署」(sign) 並載明權利義務。(A) complaint 抱怨 (B) campaign 活動 (D) conflict 衝突，皆不能簽署。故選 (C)。", "level": "B1", "topic": "employment"}, {"id": "M005", "type": "vocab", "q": "To ______ energy, our school turns off the air conditioners in empty classrooms.", "options": ["consume", "produce", "conserve", "release"], "answer": 2, "explain": "句意：為了節約能源，我們學校會關掉空教室裡的冷氣。conserve energy 節約能源。(A) consume 消耗，與目的相反 (B) produce 生產 (D) release 釋放，皆不符合「關冷氣」的目的。故選 (C)。", "level": "B2", "topic": "energy saving"}, {"id": "M006", "type": "vocab", "q": "The road was covered with ice. ______, no one was hurt when the bus slid off the road.", "options": ["Luckily", "Carelessly", "Recently", "Exactly"], "answer": 0, "explain": "句意：路面結冰了。幸運的是，巴士滑出路面時沒有人受傷。Luckily 幸運地，用來表達慶幸的語氣。(B) Carelessly 粗心地 (C) Recently 最近 (D) Exactly 確切地，皆無法銜接「沒有人受傷」的慶幸語氣。故選 (A)。", "level": "B1", "topic": "traffic accident"}, {"id": "M007", "type": "vocab", "q": "This movie is not ______ for young children because it contains many violent scenes.", "options": ["similar", "famous", "polite", "suitable"], "answer": 3, "explain": "句意：這部電影不適合幼童觀看，因為裡面有很多暴力場面。be suitable for 適合……。(A) similar 相似的（應接 to）(B) famous 有名的 (C) polite 有禮貌的，語意皆不通。故選 (D)。", "level": "B1", "topic": "movies"}, {"id": "M008", "type": "vocab", "q": "The company's main ______ this year is to reduce plastic waste by 50 percent.", "options": ["admission", "objective", "occupation", "decoration"], "answer": 1, "explain": "句意：公司今年的主要目標是將塑膠廢棄物減少 50%。objective 目標，後接 to V 說明要達成的事。(A) admission 入場；入學許可 (C) occupation 職業 (D) decoration 裝飾，皆不符語意。故選 (B)。", "level": "B2", "topic": "business goals"}, {"id": "M009", "type": "vocab", "q": "Could you ______ me your umbrella? I left mine at home, and it's raining hard.", "options": ["lend", "borrow", "return", "owe"], "answer": 0, "explain": "句意：你可以借我你的雨傘嗎？我把我的留在家裡，而且雨下得很大。lend sb sth 借（出）某物給某人。(B) borrow 是「向別人借入」，用法為 borrow sth from sb (C) return 歸還，但雨傘本來就是對方的，談不上「還給我」(D) owe 欠，皆不符語意。故選 (A)。", "level": "B1", "topic": "everyday requests"}, {"id": "M010", "type": "vocab", "q": "The instructions for the new printer were so ______ that nobody in the office could figure out how to set it up.", "options": ["practical", "accurate", "convenient", "complicated"], "answer": 3, "explain": "句意：新印表機的說明書太複雜了，辦公室裡沒有人搞得懂要如何安裝。complicated 複雜的，與 so...that nobody could figure out 呼應。(A) practical 實用的 (B) accurate 準確的 (C) convenient 方便的，都是正面意思，與後半句矛盾。故選 (D)。", "level": "B2", "topic": "office equipment"}, {"id": "M011", "type": "vocab", "q": "After graduating from high school, Kevin plans to get a part-time job to gain some work ______.", "options": ["knowledge", "product", "experience", "success"], "answer": 2, "explain": "句意：高中畢業後，Kevin 打算找份兼職工作，累積一些工作經驗。gain work experience 累積工作經驗，為常見搭配。(A) knowledge 知識（不說 gain work knowledge）(B) product 產品 (D) success 成功，皆不符搭配。故選 (C)。", "level": "B1", "topic": "part-time jobs"}, {"id": "M012", "type": "vocab", "q": "The police are still trying to ______ the cause of the fire that destroyed the old warehouse.", "options": ["decorate", "determine", "delay", "deliver"], "answer": 1, "explain": "句意：警方仍在試圖查明燒毀舊倉庫的火災起因。determine the cause 查明原因。(A) decorate 裝飾 (C) delay 延遲 (D) deliver 遞送，皆無法與「起因」搭配。故選 (B)。", "level": "B2", "topic": "news"}, {"id": "M013", "type": "vocab", "q": "The night market is always ______ on Saturday nights; you can hardly move because there are so many people.", "options": ["empty", "silent", "peaceful", "crowded"], "answer": 3, "explain": "句意：夜市每到週六晚上總是很擁擠，人多到你幾乎動不了。crowded 擁擠的。(A) empty 空的 (B) silent 安靜的 (C) peaceful 寧靜的，皆與「人很多」矛盾。故選 (D)。", "level": "B1", "topic": "night markets"}, {"id": "M014", "type": "vocab", "q": "Studying abroad can broaden your ______ and help you understand different cultures.", "options": ["horizons", "obstacles", "statistics", "minorities"], "answer": 0, "explain": "句意：出國讀書可以開拓你的視野，幫助你了解不同的文化。broaden one's horizons 開拓視野，為固定搭配。(B) obstacles 障礙 (C) statistics 統計數字 (D) minorities 少數族群，皆不符語意。故選 (A)。", "level": "B2", "topic": "studying abroad"}, {"id": "M015", "type": "vocab", "q": "Please ______ the form with your name, address, and phone number, and then hand it to the front desk.", "options": ["complain", "complete", "compete", "compare"], "answer": 1, "explain": "句意：請在表格上填寫姓名、地址和電話，然後交給櫃台。complete the form 填寫（完成）表格。(A) complain 抱怨 (C) compete 競爭 (D) compare 比較，皆為字形相近的干擾選項，語意不通。故選 (B)。", "level": "B1", "topic": "forms"}, {"id": "M016", "type": "vocab", "q": "Mr. Lin speaks English slowly and ______, so even beginners can follow what he says.", "options": ["rudely", "rarely", "clearly", "nearly"], "answer": 2, "explain": "句意：林老師說英文說得又慢又清楚，所以連初學者都聽得懂。clearly 清楚地，與 slowly 並列，且能讓初學者聽懂。(A) rudely 無禮地 (B) rarely 很少 (D) nearly 幾乎，皆不合語意。故選 (C)。", "level": "B1", "topic": "teaching"}, {"id": "M017", "type": "vocab", "q": "The mountain trail is ______ only in summer; it is closed in winter because of heavy snow.", "options": ["accessible", "valuable", "flexible", "generous"], "answer": 0, "explain": "句意：這條山路只有夏天才能通行；冬天會因大雪而封閉。accessible 可進入的、可到達的，與 closed 形成對比。(B) valuable 有價值的 (C) flexible 有彈性的 (D) generous 慷慨的，皆無法與「封閉」對照。故選 (A)。", "level": "B2", "topic": "hiking"}, {"id": "M018", "type": "vocab", "q": "The school library has a large ______ of English novels, magazines, and comic books.", "options": ["direction", "reaction", "connection", "collection"], "answer": 3, "explain": "句意：學校圖書館收藏了大量的英文小說、雜誌和漫畫。a large collection of 大量的收藏。(A) direction 方向 (B) reaction 反應 (C) connection 連結，皆不能表示書籍的收藏。故選 (D)。", "level": "B1", "topic": "library"}, {"id": "M019", "type": "vocab", "q": "The new law will ______ drivers from using mobile phones while driving.", "options": ["encourage", "prohibit", "permit", "persuade"], "answer": 1, "explain": "句意：新法將禁止駕駛人在開車時使用手機。prohibit sb from V-ing 禁止某人做某事。(A) encourage 鼓勵 (C) permit 允許 (D) persuade 說服，用法皆為 sb to V，不接 from V-ing，且語意也不合理。故選 (B)。", "level": "B2", "topic": "traffic laws"}, {"id": "M020", "type": "vocab", "q": "I'm ______ of spiders, so I always ask my brother to get them out of my room.", "options": ["proud", "jealous", "afraid", "fond"], "answer": 2, "explain": "句意：我很怕蜘蛛，所以總是請哥哥把牠們弄出我的房間。be afraid of 害怕。(A) be proud of 以……為傲 (B) be jealous of 嫉妒 (D) be fond of 喜愛，皆與「請哥哥把蜘蛛弄走」不符。故選 (C)。", "level": "B1", "topic": "fears"}, {"id": "M021", "type": "vocab", "q": "The travel agency made all the ______ for our trip, including hotel rooms and train tickets.", "options": ["achievements", "appointments", "advertisements", "arrangements"], "answer": 3, "explain": "句意：旅行社為我們的旅程做好了所有安排，包括飯店房間和火車票。make arrangements for 為……做安排。(A) achievements 成就 (B) appointments 約會、預約（指與人約定見面的時間）(C) advertisements 廣告，皆不符語意。故選 (D)。", "level": "B2", "topic": "travel planning"}, {"id": "M022", "type": "vocab", "q": "My mother ______ me to take an umbrella because the weather report said it would rain.", "options": ["reminded", "remembered", "recorded", "repeated"], "answer": 0, "explain": "句意：媽媽提醒我帶雨傘，因為氣象報告說會下雨。remind sb to V 提醒某人做某事。(B) remember 記得，不接 sb to V (C) record 記錄 (D) repeat 重複，皆不合用法與語意。故選 (A)。", "level": "B1", "topic": "family life"}, {"id": "M023", "type": "vocab", "q": "Smoking is ______ banned in all public buildings, and anyone who breaks the rule will be fined.", "options": ["frankly", "slightly", "strictly", "privately"], "answer": 2, "explain": "句意：所有公共建築都嚴格禁菸，違規者將被罰款。strictly banned 嚴格禁止。(A) frankly 坦白地 (B) slightly 稍微地，與罰款的嚴厲語氣矛盾 (D) privately 私下地，皆不合語意。故選 (C)。", "level": "B2", "topic": "public rules"}, {"id": "M024", "type": "vocab", "q": "Taiwan's night markets attract many foreign ______ who come to try local snacks during their vacations.", "options": ["residents", "tourists", "citizens", "employees"], "answer": 1, "explain": "句意：台灣的夜市吸引許多外國觀光客，他們在假期中前來品嚐當地小吃。tourists 觀光客，與 during their vacations 呼應。(A) residents 居民 (C) citizens 公民 (D) employees 員工，皆與「趁假期來品嚐小吃」不符。故選 (B)。", "level": "B1", "topic": "tourism"}, {"id": "M025", "type": "vocab", "q": "The factory was forced to ______ more than 200 workers after its sales dropped sharply.", "options": ["dismiss", "hire", "promote", "reward"], "answer": 0, "explain": "句意：銷售額大幅下滑後，這家工廠被迫解僱兩百多名工人。dismiss 解僱。(B) hire 僱用 (C) promote 升遷 (D) reward 獎勵，皆與「銷售下滑、被迫」的情境矛盾。故選 (A)。", "level": "B2", "topic": "business"}, {"id": "M026", "type": "vocab", "q": "Drinking enough water is ______ for good health, especially on hot summer days.", "options": ["harmful", "useless", "terrible", "essential"], "answer": 3, "explain": "句意：喝足夠的水對健康是不可或缺的，尤其在炎熱的夏天。essential 必要的、不可或缺的。(A) harmful 有害的 (B) useless 無用的 (C) terrible 糟糕的，皆與語意相反。故選 (D)。", "level": "B2", "topic": "health"}, {"id": "M027", "type": "vocab", "q": "The scientist won an award for her important ______ to cancer research.", "options": ["contest", "contribution", "constitution", "consumption"], "answer": 1, "explain": "句意：這位科學家因對癌症研究的重要貢獻而獲獎。contribution to 對……的貢獻。(A) contest 比賽 (C) constitution 憲法 (D) consumption 消耗，皆為字形相近的干擾選項，語意不通。故選 (B)。", "level": "B2", "topic": "science"}, {"id": "M028", "type": "vocab", "q": "Please ______ your seat belt. The plane is about to take off.", "options": ["loosen", "unlock", "fasten", "button"], "answer": 2, "explain": "句意：請繫好安全帶，飛機即將起飛。fasten one's seat belt 繫好安全帶。(A) loosen 鬆開，與語意相反 (B) unlock 解鎖 (D) button 扣（鈕扣），不與 seat belt 搭配。故選 (C)。", "level": "B1", "topic": "air travel"}, {"id": "M029", "type": "vocab", "q": "The restaurant's location is very ______; it's just a five-minute walk from the MRT station.", "options": ["convenient", "delicious", "expensive", "comfortable"], "answer": 0, "explain": "句意：這家餐廳的位置非常便利，從捷運站走路只要五分鐘。convenient 方便的。(B) delicious 美味的 (C) expensive 昂貴的 (D) comfortable 舒適的，皆不能用來形容「位置靠近捷運站」。故選 (A)。", "level": "B1", "topic": "restaurants"}, {"id": "M030", "type": "vocab", "q": "The company has a strict ______ against using personal phones during working hours.", "options": ["habit", "theory", "survey", "policy"], "answer": 3, "explain": "句意：公司有嚴格的規定，禁止員工在上班時間使用私人手機。policy 政策、規定，常與 strict 及 against 搭配。(A) habit 習慣 (B) theory 理論 (C) survey 調查，皆不能表示公司規定。故選 (D)。", "level": "B2", "topic": "company policy"}, {"id": "M031", "type": "vocab", "q": "After the earthquake, volunteers worked day and night to ______ food and water to the victims.", "options": ["estimate", "attract", "distribute", "observe"], "answer": 2, "explain": "句意：地震過後，志工們日以繼夜地發放食物和飲水給災民。distribute sth to sb 分發某物給某人。(A) estimate 估計 (B) attract 吸引 (D) observe 觀察，皆不合語意。故選 (C)。", "level": "B2", "topic": "disaster relief"}, {"id": "M032", "type": "vocab", "q": "There is a big ______ between the prices in the city and those in the countryside.", "options": ["difference", "distance", "decision", "discussion"], "answer": 0, "explain": "句意：城市和鄉村的物價有很大的差異。difference between A and B 指 A 與 B 之間的差異。(B) distance 距離，不用於比較價格 (C) decision 決定 (D) discussion 討論，皆不合語意。故選 (A)。", "level": "B1", "topic": "cost of living"}, {"id": "M033", "type": "vocab", "q": "Our class leader is very ______; she always plans ahead and never misses a deadline.", "options": ["aggressive", "organized", "stubborn", "anxious"], "answer": 1, "explain": "句意：我們的班長做事很有條理，她總是事先計畫，從不錯過截止期限。organized 有條理的。(A) aggressive 好鬥的 (C) stubborn 固執的 (D) anxious 焦慮的，皆與「事先計畫、準時完成」的描述不符。故選 (B)。", "level": "B1", "topic": "school life"}, {"id": "M034", "type": "vocab", "q": "If you don't ______ the flowers every day, they will dry up and die in this hot weather.", "options": ["pick", "cut", "wash", "water"], "answer": 3, "explain": "句意：如果你不每天幫這些花澆水，它們在這種炎熱的天氣裡會乾枯死掉。water 當動詞為「澆水」。(A) pick 摘 (B) cut 剪 (C) wash 清洗，皆無法避免花朵乾枯。故選 (D)。", "level": "B1", "topic": "gardening"}, {"id": "M035", "type": "vocab", "q": "Regular exercise can improve your blood ______ and lower your risk of heart disease.", "options": ["population", "celebration", "circulation", "pollution"], "answer": 2, "explain": "句意：規律運動可以促進血液循環，並降低罹患心臟病的風險。blood circulation 血液循環。(A) population 人口 (B) celebration 慶祝 (D) pollution 污染，皆不能與 blood 搭配。故選 (C)。", "level": "B2", "topic": "exercise"}, {"id": "M036", "type": "vocab", "q": "I ______ go to the movies; I only go once or twice a year.", "options": ["usually", "rarely", "always", "often"], "answer": 1, "explain": "句意：我很少去看電影，一年只去一、兩次。rarely 很少，與「一年一兩次」相符。(A) usually 通常 (C) always 總是 (D) often 經常，皆與很低的頻率矛盾。故選 (B)。", "level": "B1", "topic": "hobbies"}, {"id": "M037", "type": "vocab", "q": "The new manager quickly ______ the trust of her team by listening carefully to everyone's ideas.", "options": ["earned", "wasted", "owed", "refused"], "answer": 0, "explain": "句意：新經理認真傾聽每個人的想法，很快就贏得了團隊的信任。earn sb's trust 贏得某人的信任。(B) wasted 浪費 (C) owed 欠 (D) refused 拒絕，皆與「認真傾聽」帶來的正面結果不符。故選 (A)。", "level": "B2", "topic": "leadership"}, {"id": "M038", "type": "vocab", "q": "It was very ______ of you to help that old woman carry her heavy bags upstairs.", "options": ["rude", "lazy", "kind", "selfish"], "answer": 2, "explain": "句意：你真好心，幫那位老太太把沉重的袋子提上樓。It is kind of sb to V 表示「某人做某事真好心」。(A) rude 無禮的 (B) lazy 懶惰的 (D) selfish 自私的，皆與幫助他人的行為矛盾。故選 (C)。", "level": "B1", "topic": "manners"}, {"id": "M039", "type": "vocab", "q": "The ______ of the new shopping mall took three years and created hundreds of jobs for local workers.", "options": ["destruction", "instruction", "introduction", "construction"], "answer": 3, "explain": "句意：新購物中心的興建花了三年，為當地勞工創造了數百個工作機會。construction 建造、興建。(A) destruction 破壞 (B) instruction 指示 (C) introduction 介紹，皆不符語意。故選 (D)。", "level": "B2", "topic": "urban development"}, {"id": "M040", "type": "vocab", "q": "Tom ______ his leg while playing basketball, so he had to stay in the hospital for a week.", "options": ["stretched", "broke", "shook", "folded"], "answer": 1, "explain": "句意：Tom 打籃球時摔斷了腿，所以必須住院一週。break one's leg 摔斷腿。(A) stretched 伸展 (C) shook 搖動 (D) folded 摺疊，皆不會導致住院。故選 (B)。", "level": "B1", "topic": "sports injuries"}, {"id": "M041", "type": "vocab", "q": "The sales report shows a ______ increase in online orders, from 2,000 to 8,000 in just one year.", "options": ["significant", "slight", "previous", "ordinary"], "answer": 0, "explain": "句意：銷售報告顯示網路訂單大幅增加，一年內從兩千筆成長到八千筆。significant 顯著的、大幅的。(B) slight 輕微的，與四倍成長矛盾 (C) previous 先前的 (D) ordinary 普通的，皆不合語意。故選 (A)。", "level": "B2", "topic": "sales reports"}, {"id": "M042", "type": "vocab", "q": "Excuse me, could you give me ______ to the train station? I think I'm lost.", "options": ["decisions", "suggestions", "directions", "descriptions"], "answer": 2, "explain": "句意：不好意思，可以告訴我去火車站怎麼走嗎？我好像迷路了。directions to + 地點，指路、方向指引。(A) decisions 決定 (B) suggestions 建議 (D) descriptions 描述，皆不能與 to the train station 搭配表示問路。故選 (C)。", "level": "B1", "topic": "asking directions"}, {"id": "M043", "type": "vocab", "q": "Hundreds of workers gathered outside the factory to ______ against low pay and long working hours.", "options": ["promote", "preserve", "predict", "protest"], "answer": 3, "explain": "句意：數百名工人聚集在工廠外，抗議低薪和過長的工時。protest against 抗議……。(A) promote 推廣 (B) preserve 保存 (C) predict 預測，皆不能接 against 表示反對。故選 (D)。", "level": "B2", "topic": "labor issues"}, {"id": "M044", "type": "vocab", "q": "The weather was so ______ that we decided to stay home and watch movies instead of going to the beach.", "options": ["sunny", "terrible", "pleasant", "warm"], "answer": 1, "explain": "句意：天氣太糟了，所以我們決定待在家看電影，而不去海邊。terrible 糟糕的。(A) sunny 晴朗的 (C) pleasant 宜人的 (D) warm 溫暖的，都是適合去海邊的好天氣，與後半句矛盾。故選 (B)。", "level": "B1", "topic": "weather"}, {"id": "M045", "type": "vocab", "q": "Online shopping has gained great ______ among teenagers because it is fast and convenient.", "options": ["popularity", "possibility", "personality", "publicity"], "answer": 0, "explain": "句意：網路購物因為快速又方便，在青少年之間大受歡迎。gain popularity among 在……之間受歡迎。(B) possibility 可能性 (C) personality 個性 (D) publicity 宣傳、媒體關注，皆不符「因方便而受青睞」的語意。故選 (A)。", "level": "B2", "topic": "online shopping"}, {"id": "M046", "type": "vocab", "q": "We need to ______ a table at the restaurant because it's always full on Friday nights.", "options": ["order", "serve", "reserve", "prepare"], "answer": 2, "explain": "句意：我們需要先訂位，因為那家餐廳週五晚上總是客滿。reserve a table 預約餐桌、訂位。(A) order 點（餐）(B) serve 供應 (D) prepare 準備，皆不能與 a table 搭配表示訂位。故選 (C)。", "level": "B1", "topic": "restaurant booking"}, {"id": "M047", "type": "vocab", "q": "The final exam was ______ difficult; most students couldn't finish it in time.", "options": ["hardly", "extremely", "slightly", "rarely"], "answer": 1, "explain": "句意：期末考非常難，大部分學生都無法及時寫完。extremely 極度地。(A) hardly 幾乎不 (C) slightly 稍微 (D) rarely 很少，皆與「大部分學生寫不完」矛盾。故選 (B)。", "level": "B1", "topic": "exams"}, {"id": "M048", "type": "vocab", "q": "The weather in the mountains is ______; it can be sunny one minute and rainy the next.", "options": ["constant", "reliable", "steady", "unpredictable"], "answer": 3, "explain": "句意：山上的天氣難以預測，可能這一分鐘是晴天，下一分鐘就下雨。unpredictable 無法預測的。(A) constant 不變的 (B) reliable 可靠的 (C) steady 穩定的，皆與「變化快速」相反。故選 (D)。", "level": "B2", "topic": "mountain weather"}, {"id": "M049", "type": "vocab", "q": "I have an ______ with the dentist at 3 p.m., so I need to leave school early today.", "options": ["appointment", "agreement", "assignment", "environment"], "answer": 0, "explain": "句意：我下午三點跟牙醫有約診，所以今天要提早離開學校。have an appointment with sb 與某人有約（看診、會面）。(B) agreement 協議 (C) assignment 作業、任務 (D) environment 環境，皆不符語意。故選 (A)。", "level": "B1", "topic": "appointments"}, {"id": "M050", "type": "vocab", "q": "This medicine can ______ your headache quickly, but it may make you feel sleepy.", "options": ["increase", "release", "relieve", "receive"], "answer": 2, "explain": "句意：這種藥能迅速緩解頭痛，但可能會讓你想睡。relieve 減輕、緩解（疼痛）。(A) increase 增加，與藥效相反 (B) release 釋放 (D) receive 收到，皆為字形相近的干擾選項。故選 (C)。", "level": "B2", "topic": "medicine"}, {"id": "M051", "type": "vocab", "q": "Before boarding an international flight, all passengers must show their ______ and boarding pass at the gate.", "options": ["receipt", "brochure", "passport", "coupon"], "answer": 2, "explain": "句意：搭乘國際航班登機前，所有乘客都必須在登機門出示______和登機證。(A) receipt 收據 (B) brochure 小冊子 (C) passport 護照 (D) coupon 優惠券。搭國際線須出示「護照」與登機證，passport 符合語意；receipt、brochure、coupon 都不是登機時查驗的證件。故選 (C)。", "level": "B1", "topic": "travel"}, {"id": "M052", "type": "vocab", "q": "Mr. Lin asked the students to ______ their essays before Friday so that he could grade them over the weekend.", "options": ["submit", "admit", "permit", "commit"], "answer": 0, "explain": "句意：林老師要學生在星期五前______作文，好讓他週末批改。(A) submit 繳交、提交 (B) admit 承認；准許進入 (C) permit 允許 (D) commit 犯（錯、罪）；承諾。submit an essay 指「繳交作文」，符合老師要批改的語境；其餘三字雖同為 -mit 結尾，意思都不合。故選 (A)。", "level": "B2", "topic": "school"}, {"id": "M053", "type": "vocab", "q": "It was so ______ on the highway this morning that drivers had to slow down and turn on their lights because they could not see far ahead.", "options": ["sunny", "chilly", "windy", "foggy"], "answer": 3, "explain": "句意：今天早上高速公路上______到駕駛人必須減速並打開車燈，因為他們看不清前方。(A) sunny 晴朗的 (B) chilly 寒冷的 (C) windy 風大的 (D) foggy 有霧的。「看不清前方、要開燈」表示能見度很低，只有 foggy（起霧）會造成這種情況；晴朗、寒冷或風大的天氣都不會讓人看不見前方。故選 (D)。", "level": "B1", "topic": "weather"}, {"id": "M054", "type": "vocab", "q": "After working at the company for ten years, Ms. Chen finally got a ______ to sales manager.", "options": ["pension", "promotion", "permission", "profession"], "answer": 1, "explain": "句意：在公司工作十年後，陳小姐終於獲得______，成為業務經理。(A) pension 退休金 (B) promotion 升遷 (C) permission 許可 (D) profession 職業。get a promotion to + 職位 表「升為某職位」；pension 是退休後領的錢，permission、profession 都無法接 to sales manager 表示升職。故選 (B)。", "level": "B1", "topic": "workplace"}, {"id": "M055", "type": "vocab", "q": "Eating too much sugar is ______ to your teeth, so try to cut down on sweets and soft drinks.", "options": ["harmful", "grateful", "faithful", "peaceful"], "answer": 0, "explain": "句意：吃太多糖對牙齒______，所以要試著少吃甜食、少喝汽水。(A) harmful 有害的 (B) grateful 感激的 (C) faithful 忠實的 (D) peaceful 和平的。be harmful to 表「對……有害」，符合要少吃甜食的建議；grateful、faithful、peaceful 皆與健康無關，語意不通。故選 (A)。", "level": "B1", "topic": "health"}, {"id": "M056", "type": "vocab", "q": "Factories that ______ waste into rivers will have to pay heavy fines, since this seriously harms the fish and the water we drink.", "options": ["donate", "inspire", "dump", "attract"], "answer": 2, "explain": "句意：將廢棄物______到河川裡的工廠將被處以高額罰款，因為這會嚴重傷害魚類和我們的飲用水。(A) donate 捐贈 (B) inspire 啟發 (C) dump 傾倒、丟棄 (D) attract 吸引。dump waste into rivers 表「把廢棄物倒入河川」，正是會被罰款的污染行為；捐贈、啟發、吸引廢棄物到河裡都不合語意，也不會因此被罰。故選 (C)。", "level": "B2", "topic": "environment"}, {"id": "M057", "type": "vocab", "q": "The baby was sleeping, so Kevin closed the door ______ to avoid waking her up.", "options": ["loudly", "rapidly", "angrily", "quietly"], "answer": 3, "explain": "句意：寶寶正在睡覺，所以 Kevin ______關上門，以免吵醒她。(A) loudly 大聲地 (B) rapidly 快速地 (C) angrily 生氣地 (D) quietly 安靜地、輕聲地。為了不吵醒寶寶，應「輕輕地、安靜地」關門；大聲、快速、生氣地關門反而容易吵醒她。故選 (D)。", "level": "B1", "topic": "family"}, {"id": "M058", "type": "vocab", "q": "If you are not satisfied with the product, you can return it within seven days and get a full ______.", "options": ["reward", "refund", "record", "report"], "answer": 1, "explain": "句意：如果您對產品不滿意，可以在七天內退貨並獲得全額______。(A) reward 報酬、獎賞 (B) refund 退款 (C) record 紀錄 (D) report 報告。get a full refund 是「獲得全額退款」的固定搭配，與退貨語境相符；reward 是因表現好而得到的獎賞，record、report 與退貨無關。故選 (B)。", "level": "B2", "topic": "shopping"}, {"id": "M059", "type": "vocab", "q": "Many students use apps on their phones to ______ new English words while they are waiting for the bus.", "options": ["criticize", "apologize", "memorize", "realize"], "answer": 2, "explain": "句意：許多學生在等公車時，用手機上的應用程式來______新的英文單字。(A) criticize 批評 (B) apologize 道歉 (C) memorize 記住、背誦 (D) realize 了解；實現。memorize new words 表「背單字」，符合語意；批評單字、realize 單字皆不合理，apologize 為不及物動詞，也不能直接接受詞。故選 (C)。", "level": "B1", "topic": "technology"}, {"id": "M060", "type": "vocab", "q": "The job requires someone who is ______ in both English and Japanese, since the company deals with clients from both countries.", "options": ["fluent", "fragile", "frequent", "furious"], "answer": 0, "explain": "句意：這份工作需要英語和日語都______的人，因為公司要和這兩個國家的客戶往來。(A) fluent 流利的 (B) fragile 易碎的 (C) frequent 頻繁的 (D) furious 狂怒的。be fluent in + 語言 表「某語言很流利」；fragile 形容物品易碎，frequent 指次數頻繁，furious 指非常生氣，都無法形容語言能力。故選 (A)。", "level": "B2", "topic": "workplace"}, {"id": "M061", "type": "vocab", "q": "The school nurse took my ______ and told me that I had a slight fever, so I should go home and rest.", "options": ["attitude", "temperature", "signature", "furniture"], "answer": 1, "explain": "句意：學校護理師幫我量了______，告訴我有點發燒，要我回家休息。(A) attitude 態度 (B) temperature 體溫、溫度 (C) signature 簽名 (D) furniture 家具。take one's temperature 表「量某人的體溫」，量完才知道「有點發燒」；attitude、signature、furniture 雖然字尾相似，但都無法「量」出是否發燒。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M062", "type": "vocab", "q": "Scientists are trying to ______ a vaccine that can protect people from the new virus.", "options": ["describe", "destroy", "deserve", "develop"], "answer": 3, "explain": "句意：科學家正努力______一種能保護人們免受新病毒感染的疫苗。(A) describe 描述 (B) destroy 摧毀 (C) deserve 應得 (D) develop 研發、發展。develop a vaccine 表「研發疫苗」；描述或摧毀疫苗與「保護人們」的目的不符，deserve 意思也不通。故選 (D)。", "level": "B1", "topic": "science"}, {"id": "M063", "type": "vocab", "q": "A passerby called an ambulance and stayed with the ______ of the car accident until help arrived.", "options": ["victims", "critics", "rivals", "hosts"], "answer": 0, "explain": "句意：一位路人叫了救護車，並陪著這場車禍的______直到救援抵達。(A) victims 受害者、傷者 (B) critics 批評者 (C) rivals 對手 (D) hosts 主人；主持人。the victims of the accident 表「事故的受害者」，需要救護車的正是車禍中受傷的人；批評者、對手、主人都不是車禍中需要救助的對象。故選 (A)。", "level": "B2", "topic": "accident"}, {"id": "M064", "type": "vocab", "q": "David is very ______; he always does his share of the work in group projects and never forgets his duties.", "options": ["talkative", "cheerful", "responsible", "humorous"], "answer": 2, "explain": "句意：David 非常______，他在小組作業中總是做好自己分內的工作，也從不忘記自己的職責。(A) talkative 健談的 (B) cheerful 開朗的 (C) responsible 負責任的 (D) humorous 幽默的。做好分內工作、不忘職責是「負責任」的表現；健談、開朗、幽默描述的是個性或說話方式，無法說明分號後的行為。故選 (C)。", "level": "B1", "topic": "personality"}, {"id": "M065", "type": "vocab", "q": "Our flight was ______ for three hours because of the heavy storm, so we had to wait at the airport.", "options": ["invited", "delayed", "rescued", "allowed"], "answer": 1, "explain": "句意：因為強烈暴風雨，我們的班機______了三個小時，只好在機場等候。(A) invited 邀請 (B) delayed 延誤 (C) rescued 救援 (D) allowed 允許。be delayed for three hours 表「延誤三小時」，與「在機場等候」相符；班機被邀請、被救援、被允許三小時都不合邏輯。故選 (B)。", "level": "B1", "topic": "travel"}, {"id": "M066", "type": "vocab", "q": "The new smartphone was so popular that the company could not keep up with the ______; stores ran out of it within hours.", "options": ["supply", "budget", "status", "demand"], "answer": 3, "explain": "句意：這款新手機非常熱門，公司根本趕不上______，商店在幾小時內就賣光了。(A) supply 供應 (B) budget 預算 (C) status 地位 (D) demand 需求。keep up with demand 表「跟上需求、滿足需求」；產品熱賣代表市場「需求」大，公司本身就是供應的一方，所以不是 supply；budget、status 與賣光無關。故選 (D)。", "level": "B2", "topic": "business"}, {"id": "M067", "type": "vocab", "q": "Tom ______ dropped his phone into the swimming pool while he was taking a selfie.", "options": ["proudly", "honestly", "accidentally", "patiently"], "answer": 2, "explain": "句意：Tom 在自拍時______把手機掉進了游泳池。(A) proudly 驕傲地 (B) honestly 誠實地 (C) accidentally 意外地、不小心地 (D) patiently 耐心地。手機掉進泳池是「不小心」造成的，accidentally 最合理；驕傲地、誠實地、耐心地把手機掉進水裡都不合常理。故選 (C)。", "level": "B1", "topic": "daily life"}, {"id": "M068", "type": "vocab", "q": "To ______ cheating, teachers make sure that all students' phones are turned off and put in their bags before the exam begins.", "options": ["prevent", "promote", "predict", "permit"], "answer": 0, "explain": "句意：為了______作弊，老師在考試開始前會確認所有學生的手機都已關機並收進書包。(A) prevent 預防、防止 (B) promote 促進；升遷 (C) predict 預測 (D) permit 允許。收走手機是為了「防止」作弊，prevent cheating 合理；promote、permit 意思與目的相反，predict 作弊也不合邏輯。故選 (A)。", "level": "B2", "topic": "school"}, {"id": "M069", "type": "vocab", "q": "This milk smells ______; it must have been left out of the fridge for too long.", "options": ["fresh", "spicy", "crispy", "sour"], "answer": 3, "explain": "句意：這瓶牛奶聞起來______，一定是放在冰箱外太久了。(A) fresh 新鮮的 (B) spicy 辣的 (C) crispy 酥脆的 (D) sour 酸的。牛奶放在室溫太久會變質發酸，smell sour 合理；fresh 與「放太久」矛盾，spicy、crispy 不適合形容牛奶的氣味。故選 (D)。", "level": "B1", "topic": "food"}, {"id": "M070", "type": "vocab", "q": "Going to bed late every night has become a bad ______ for many students, and it affects their health.", "options": ["hobby", "habit", "chance", "gift"], "answer": 1, "explain": "句意：每天晚睡已成為許多學生的壞______，而且影響了他們的健康。(A) hobby 嗜好 (B) habit 習慣 (C) chance 機會 (D) gift 禮物；天賦。a bad habit 表「壞習慣」，每天晚睡是日常養成的行為；hobby 指休閒時喜愛從事的活動，不是作息習慣；chance、gift 語意不通。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M071", "type": "vocab", "q": "The hotel guest decided to ______ to the manager because his room was dirty and the air conditioner did not work.", "options": ["complain", "compete", "concern", "consist"], "answer": 0, "explain": "句意：這位飯店房客決定向經理______，因為他的房間很髒，冷氣也壞了。(A) complain 抱怨、投訴 (B) compete 競爭 (C) concern 使擔心；與……有關 (D) consist 組成。complain to sb. 表「向某人投訴」，符合房間髒亂的情境；compete、concern 與投訴無關，consist 須接 of 表示「由……組成」。故選 (A)。", "level": "B1", "topic": "customer service"}, {"id": "M072", "type": "vocab", "q": "This laptop is light and ______, so you can easily carry it around in your backpack.", "options": ["visible", "audible", "portable", "edible"], "answer": 2, "explain": "句意：這台筆電又輕又______，所以你可以輕鬆地把它放在背包裡帶著走。(A) visible 看得見的 (B) audible 聽得見的 (C) portable 可攜帶的、輕便的 (D) edible 可食用的。portable 由 port（攜帶）+ -able 組成，表「便於攜帶的」，與「放背包帶著走」相符；其餘三字皆與攜帶無關。故選 (C)。", "level": "B2", "topic": "technology"}, {"id": "M073", "type": "vocab", "q": "Air ______ in the city has become worse because of the growing number of cars and factories.", "options": ["population", "pollution", "position", "portion"], "answer": 1, "explain": "句意：由於汽車和工廠的數量不斷增加，市區的空氣______變得更嚴重了。(A) population 人口 (B) pollution 污染 (C) position 位置 (D) portion 部分。air pollution 表「空氣污染」，與汽車、工廠增加的原因相符；population 字形相近但意思是人口，position、portion 也無法與 air 搭配。故選 (B)。", "level": "B1", "topic": "environment"}, {"id": "M074", "type": "vocab", "q": "When you ride a scooter, you must ______ a helmet to protect your head.", "options": ["dress", "put", "carry", "wear"], "answer": 3, "explain": "句意：騎機車時，你必須______安全帽來保護頭部。(A) dress 給……穿衣 (B) put 放置 (C) carry 攜帶 (D) wear 穿戴。wear a helmet 表「戴著安全帽」的狀態；dress 的受詞是人（dress the baby），不能接 helmet；put 須用 put on 才表示「戴上」；只是 carry（攜帶）安全帽無法保護頭部。故選 (D)。", "level": "B1", "topic": "safety"}, {"id": "M075", "type": "vocab", "q": "Before the job interview, Amy did some research on the company and practiced answering common questions. Her careful ______ helped her get the job.", "options": ["preparation", "imagination", "invitation", "population"], "answer": 0, "explain": "句意：面試前，Amy 研究了這家公司並練習回答常見問題，她細心的______幫助她得到了這份工作。(A) preparation 準備 (B) imagination 想像力 (C) invitation 邀請 (D) population 人口。研究公司、練習回答問題都屬於面試前的「準備」，careful preparation 表「細心的準備」；imagination、invitation、population 都與前文描述的行為不符。故選 (A)。", "level": "B2", "topic": "career"}, {"id": "M076", "type": "vocab", "q": "Vegetable prices have risen ______ since the typhoon hit; some have even doubled.", "options": ["slightly", "barely", "sharply", "rarely"], "answer": 2, "explain": "句意：颱風過後，蔬菜價格______上漲，有些甚至翻了一倍。(A) slightly 稍微地 (B) barely 幾乎沒有 (C) sharply 急遽地、大幅地 (D) rarely 很少。價格「翻倍」表示漲幅很大，rise sharply 表「急遽上升」；slightly 與翻倍矛盾，barely、rarely 也不能形容大幅上漲。故選 (C)。", "level": "B2", "topic": "economy"}, {"id": "M077", "type": "vocab", "q": "Although Ben is very ______ and rarely talks in class, he is quite friendly once you get to know him.", "options": ["generous", "honest", "brave", "shy"], "answer": 3, "explain": "句意：雖然 Ben 很______，在課堂上很少說話，但只要你跟他熟了，就會發現他相當友善。(A) generous 慷慨的 (B) honest 誠實的 (C) brave 勇敢的 (D) shy 害羞的。由 although 可知前後語意相對，「很少說話」對比「熟了之後很友善」，shy 最合理；慷慨、誠實、勇敢都與「很少說話」無關。故選 (D)。", "level": "B1", "topic": "personality"}, {"id": "M078", "type": "vocab", "q": "The two companies agreed to ______ on a new project to build electric scooters.", "options": ["compete", "cooperate", "complain", "consume"], "answer": 1, "explain": "句意：這兩家公司同意在一項製造電動機車的新計畫上______。(A) compete 競爭 (B) cooperate 合作 (C) complain 抱怨 (D) consume 消耗。cooperate on a project 表「在計畫上合作」，兩家公司「同意」一起進行新計畫，應為合作；同意互相競爭、抱怨或消耗都不合邏輯。故選 (B)。", "level": "B2", "topic": "business"}, {"id": "M079", "type": "vocab", "q": "The tour ______ explained the history of the old temple to our group in both Chinese and English.", "options": ["guide", "judge", "pilot", "clerk"], "answer": 0, "explain": "句意：這位 tour ______ 用中文和英文向我們這團解說這座古廟的歷史。(A) guide 嚮導、導遊 (B) judge 法官；裁判 (C) pilot 飛行員 (D) clerk 店員、職員。tour guide 表「導遊」，負責帶團並解說景點；judge、pilot、clerk 都不是帶團解說古蹟的人，也不能與 tour 搭配。故選 (A)。", "level": "B1", "topic": "travel"}, {"id": "M080", "type": "vocab", "q": "I forgot to ______ my alarm clock last night, so I woke up late and missed the school bus.", "options": ["raise", "ring", "set", "hold"], "answer": 2, "explain": "句意：我昨晚忘了______鬧鐘，所以睡過頭，錯過了校車。(A) raise 舉起；養育 (B) ring （鈴）響；打電話 (C) set 設定 (D) hold 握住。set an alarm (clock) 表「設定鬧鐘」，忘了設定才會睡過頭；ring 指鈴聲響起，是鬧鐘自己響，不是人睡前要做的動作；raise、hold 鬧鐘也無法說明為何睡過頭。故選 (C)。", "level": "B1", "topic": "daily life"}, {"id": "M081", "type": "vocab", "q": "Glass is ______, so light can pass through it easily and we can see what is on the other side.", "options": ["flexible", "transparent", "magnetic", "poisonous"], "answer": 1, "explain": "句意：玻璃是______的，所以光線能輕易穿過，我們也能看見另一邊的東西。(A) flexible 有彈性的、可彎曲的 (B) transparent 透明的 (C) magnetic 有磁性的 (D) poisonous 有毒的。光線能穿過、看得見另一邊，正是「透明」的特性；flexible、magnetic、poisonous 都與「光線能穿過、看得見另一邊」沒有因果關係。故選 (B)。", "level": "B2", "topic": "science"}, {"id": "M082", "type": "vocab", "q": "Because sales had been excellent, the company gave each employee a ______ of NT$20,000 at the end of the year.", "options": ["bonus", "fine", "loan", "tax"], "answer": 0, "explain": "句意：由於業績非常好，公司在年底發給每位員工兩萬元的______。(A) bonus 獎金、紅利 (B) fine 罰款 (C) loan 貸款 (D) tax 稅。因業績好而在年底發給員工的錢是「年終獎金」（year-end bonus）；fine 是罰款，loan 需要歸還，tax 是繳給政府的錢，皆不合語意。故選 (A)。", "level": "B1", "topic": "workplace"}, {"id": "M083", "type": "vocab", "q": "It took Mark two months to fully ______ from his knee injury before he could play basketball again.", "options": ["remove", "retire", "reduce", "recover"], "answer": 3, "explain": "句意：Mark 花了兩個月才從膝傷中完全______，之後才能再打籃球。(A) remove 移除 (B) retire 退休 (C) reduce 減少 (D) recover 康復。recover from an injury 表「從傷勢中康復」；remove、reduce 為及物動詞且語意不符；retire from 是「從……退休」，與傷癒後重返球場的語意矛盾。故選 (D)。", "level": "B2", "topic": "sports"}, {"id": "M084", "type": "vocab", "q": "Please turn off your cell phone during the ______; it's rude to let it ring while the actors are on stage.", "options": ["receipt", "harvest", "performance", "departure"], "answer": 2, "explain": "句意：______進行中請關閉手機；演員在台上時讓手機響是很不禮貌的。(A) receipt 收據 (B) harvest 收成 (C) performance 演出、表演 (D) departure 出發、離開。由「演員在台上」可知是在看「表演」，during the performance 合理；收據、收成、出發都與演員演出無關。故選 (C)。", "level": "B1", "topic": "entertainment"}, {"id": "M085", "type": "vocab", "q": "Lucy ______ her mother; they both have big eyes and curly hair.", "options": ["takes", "resembles", "raises", "respects"], "answer": 1, "explain": "句意：Lucy ______她的母親，她們都有大眼睛和捲髮。(A) takes 拿 (B) resembles 長得像 (C) raises 撫養；舉起 (D) respects 尊敬。resemble sb. 表「與某人相像」，後句「都有大眼睛和捲髮」正是外表相似的說明；take 須用 take after 才表示「像（父母）」，raise、respect 都不能解釋兩人外貌相同。故選 (B)。", "level": "B2", "topic": "family"}, {"id": "M086", "type": "vocab", "q": "These shoes are too ______ for me. Do you have them in a bigger size?", "options": ["tight", "loose", "cheap", "light"], "answer": 0, "explain": "句意：這雙鞋對我來說太______了，有大一點的尺寸嗎？(A) tight 緊的 (B) loose 鬆的 (C) cheap 便宜的 (D) light 輕的。想換「大一點的尺寸」，表示鞋子太緊；loose 意思相反（太鬆應換小一號），cheap、light 都不是換大尺寸的理由。故選 (A)。", "level": "B1", "topic": "shopping"}, {"id": "M087", "type": "vocab", "q": "According to a recent ______, more than 70 percent of teenagers in Taiwan spend over three hours a day on their phones.", "options": ["rumor", "tradition", "ceremony", "survey"], "answer": 3, "explain": "句意：根據最近的一項______，台灣超過百分之七十的青少年每天花三小時以上在手機上。(A) rumor 謠言 (B) tradition 傳統 (C) ceremony 典禮 (D) survey 調查。according to a survey 表「根據調查」，後面接統計數據合理；謠言不能作為數據來源，tradition、ceremony 與統計結果無關。故選 (D)。", "level": "B2", "topic": "society"}, {"id": "M088", "type": "vocab", "q": "We should ______ paper, glass, and plastic bottles instead of throwing them away with the general trash.", "options": ["replace", "repeat", "recycle", "refuse"], "answer": 2, "explain": "句意：我們應該______紙類、玻璃和塑膠瓶，而不是把它們和一般垃圾一起丟掉。(A) replace 取代 (B) repeat 重複 (C) recycle 回收 (D) refuse 拒絕。由「而不是和一般垃圾一起丟掉」可知應做資源「回收」；replace、repeat、refuse 皆不合語意。故選 (C)。", "level": "B1", "topic": "environment"}, {"id": "M089", "type": "vocab", "q": "The fire spread so ______ that the firefighters could not stop it from reaching the nearby buildings.", "options": ["rapidly", "politely", "properly", "slightly"], "answer": 0, "explain": "句意：火勢蔓延得非常______，消防員無法阻止它延燒到附近的建築物。(A) rapidly 快速地 (B) politely 有禮貌地 (C) properly 適當地 (D) slightly 稍微地。so...that 表結果：火勢蔓延「快」到無法阻止，spread rapidly 合理；politely 不能形容火，properly、slightly 也無法說明消防員為何擋不住。故選 (A)。", "level": "B2", "topic": "news"}, {"id": "M090", "type": "vocab", "q": "Thanks to the ______ of many local businesses, the community was able to build a new playground for the children.", "options": ["complaints", "donations", "competitions", "inventions"], "answer": 1, "explain": "句意：多虧許多在地商家的______，社區才得以為孩子們蓋一座新的遊樂場。(A) complaints 抱怨、投訴 (B) donations 捐款、捐贈 (C) competitions 比賽、競爭 (D) inventions 發明。thanks to 表「多虧、由於」，社區能蓋遊樂場是因為商家「捐款」；抱怨、比賽、發明都無法提供蓋遊樂場所需的資金。故選 (B)。", "level": "B2", "topic": "community"}, {"id": "M091", "type": "vocab", "q": "The museum is ______ to the public every day except Monday, from 9 a.m. to 5 p.m.", "options": ["equal", "similar", "open", "familiar"], "answer": 2, "explain": "句意：這間博物館除了星期一以外，每天上午九點到下午五點對大眾______。(A) equal 相等的 (B) similar 相似的 (C) open 開放的 (D) familiar 熟悉的。be open to the public 表「對大眾開放」，後面接開放時間合理；equal to、similar to、familiar to 雖也都接 to，但都無法搭配開放時間。故選 (C)。", "level": "B1", "topic": "travel"}, {"id": "M092", "type": "vocab", "q": "Our company plans to ______ twenty new employees next year to help with the growing business.", "options": ["fire", "quit", "retire", "hire"], "answer": 3, "explain": "句意：我們公司計畫明年______二十名新員工，以因應日益成長的業務。(A) fire 開除 (B) quit 辭職 (C) retire 退休 (D) hire 雇用。業務成長需要更多人手，hire new employees 表「雇用新員工」；fire 意思相反（且不會開除「新」員工來幫忙業務），quit、retire 是員工自己離職或退休，不能以 employees 作受詞。故選 (D)。", "level": "B1", "topic": "workplace"}, {"id": "M093", "type": "vocab", "q": "Many volunteers spend their weekends at the animal ______, feeding and walking dogs that have no homes.", "options": ["shelter", "factory", "harbor", "studio"], "answer": 0, "explain": "句意：許多志工利用週末到動物______幫忙，餵食並帶無家可歸的狗散步。(A) shelter 收容所、庇護所 (B) factory 工廠 (C) harbor 港口 (D) studio 工作室。animal shelter 表「動物收容所」，收容流浪動物；factory、harbor、studio 都不是照顧無家可歸狗兒的地方。故選 (A)。", "level": "B2", "topic": "volunteering"}, {"id": "M094", "type": "vocab", "q": "Dinosaurs became ______ about 66 million years ago, possibly because a huge asteroid hit the Earth.", "options": ["ancient", "extinct", "evident", "efficient"], "answer": 1, "explain": "句意：恐龍大約在六千六百萬年前______，可能是因為一顆巨大的小行星撞擊地球。(A) ancient 古老的 (B) extinct 滅絕的 (C) evident 明顯的 (D) efficient 有效率的。become extinct 表「滅絕」，與小行星撞擊的原因相符；ancient 雖與年代久遠有關，但 become ancient 不能表示物種消失；evident、efficient 語意不通。故選 (B)。", "level": "B2", "topic": "science"}, {"id": "M095", "type": "vocab", "q": "The teacher asked us to ______ the two poems and find out how they are similar and how they are different.", "options": ["arrange", "invent", "compare", "repair"], "answer": 2, "explain": "句意：老師要我們______這兩首詩，找出它們有哪些相同和不同之處。(A) arrange 安排 (B) invent 發明 (C) compare 比較 (D) repair 修理。找出相同與相異之處就是「比較」，compare 符合語意；安排、發明、修理這兩首詩都不合理。故選 (C)。", "level": "B1", "topic": "school"}, {"id": "M096", "type": "vocab", "q": "Our ______ to Japan included visits to Tokyo, Kyoto, and Osaka, and we enjoyed every part of it.", "options": ["luggage", "currency", "souvenir", "journey"], "answer": 3, "explain": "句意：我們的日本______包括參訪東京、京都和大阪，而且我們很享受其中的每一段。(A) luggage 行李 (B) currency 貨幣 (C) souvenir 紀念品 (D) journey 旅程。能「包括參訪三個城市」的是「旅程」，journey to Japan 合理；行李、貨幣、紀念品都不能包含參訪行程。故選 (D)。", "level": "B1", "topic": "travel"}, {"id": "M097", "type": "vocab", "q": "Many college students shop at this store because its prices are ______; most items cost less than NT$100.", "options": ["affordable", "remarkable", "comfortable", "available"], "answer": 0, "explain": "句意：許多大學生在這家店購物，因為它的價格很______，大部分商品不到一百元。(A) affordable 負擔得起的、平價的 (B) remarkable 非凡的 (C) comfortable 舒適的 (D) available 可取得的。商品多不到一百元，表示價格「平價、負擔得起」，affordable prices 合理；remarkable、comfortable 不能形容便宜的價格，available 指可買到、可取得，與便宜無關。故選 (A)。", "level": "B2", "topic": "shopping"}, {"id": "M098", "type": "vocab", "q": "If your headache doesn't go away, you should see a doctor and get a ______ for stronger medicine.", "options": ["recipe", "receipt", "prescription", "reception"], "answer": 2, "explain": "句意：如果你的頭痛一直沒好，應該去看醫生並取得______，才能拿到較強效的藥。(A) recipe 食譜 (B) receipt 收據 (C) prescription 處方箋 (D) reception 接待處；歡迎會。醫生開立、讓病人領取藥物的是「處方箋」，a prescription for medicine 為常見搭配；recipe、receipt、reception 拼字相近但意思皆不符。故選 (C)。", "level": "B2", "topic": "health"}, {"id": "M099", "type": "vocab", "q": "Our school basketball team practiced hard every day and finally ______ the championship.", "options": ["beat", "won", "gained", "lost"], "answer": 1, "explain": "句意：我們學校的籃球隊每天努力練習，終於______了冠軍。(A) beat 打敗 (B) won 贏得 (C) gained 獲得 (D) lost 輸掉。win the championship 表「贏得冠軍」；beat 的受詞應為對手（如 beat the other team），gain 多接經驗、體重等，不與 championship 搭配；lost 與「努力練習、終於」的語意矛盾。故選 (B)。", "level": "B1", "topic": "sports"}, {"id": "M100", "type": "vocab", "q": "The new employee was ______ about her first day at work, so she arrived thirty minutes early.", "options": ["ashamed", "bored", "disappointed", "anxious"], "answer": 3, "explain": "句意：這位新員工對上班第一天感到很______，所以提早三十分鐘到。(A) ashamed 羞愧的 (B) bored 無聊的 (C) disappointed 失望的 (D) anxious 焦慮的、擔心的。be anxious about 表「對……感到焦慮、擔心」，因為擔心才會提早到；第一天還沒開始上班，談不上羞愧、無聊或失望。故選 (D)。", "level": "B2", "topic": "workplace"}, {"id": "M101", "type": "grammar", "q": "My cousin ______ in Kaohsiung since she was ten years old.", "options": ["has lived", "lives", "is living", "lived"], "answer": 0, "explain": "句意：我表姊從十歲起就住在高雄。since + 過去時間點（she was ten）表示從過去持續到現在的狀態，主要子句須用現在完成式 has lived。(B) lives 為現在簡單式、(C) is living 為現在進行式，都不能搭配 since 表持續；(D) lived 為過去式，表示已結束，與 since 不合。故選 (A)。", "level": "B1", "topic": "present perfect"}, {"id": "M102", "type": "grammar", "q": "When we arrived at the theater, the movie ______, so we missed the opening scene.", "options": ["has already started", "already starts", "had already started", "will already start"], "answer": 2, "explain": "句意：我們到達戲院時，電影已經開始了，所以錯過了開場。「電影開始」發生在「我們到達（過去）」之前，屬於「過去的過去」，用過去完成式 had already started。(A) 現在完成式不能與過去時間 arrived 搭配；(B) 現在式時態不符；(D) 未來式與句意不合。故選 (C)。", "level": "B2", "topic": "past perfect"}, {"id": "M103", "type": "grammar", "q": "The new library ______ by more than 5,000 students since it opened last year.", "options": ["has visited", "has been visited", "was visited", "is visiting"], "answer": 1, "explain": "句意：新圖書館自去年開館以來，已有超過五千名學生造訪。since 表示持續到現在，須用現在完成式；圖書館是「被」學生造訪，且後有 by，故用被動 has been visited。(A) has visited 為主動，語意變成圖書館去拜訪學生；(C) was visited 為過去式，不能搭配 since；(D) is visiting 為主動進行式，時態與語態皆錯。故選 (B)。", "level": "B1", "topic": "passive voice"}, {"id": "M104", "type": "grammar", "q": "I have a classmate ______ father is a famous chef in Tainan.", "options": ["who", "which", "whom", "whose"], "answer": 3, "explain": "句意：我有一位同學，他的父親是台南的知名主廚。空格後直接接名詞 father，表示「同學的父親」，須用所有格關係代名詞 whose。(A) who 與 (C) whom 後面不可直接接名詞表所屬；(B) which 指事物，也不表所有格。故選 (D)。", "level": "B1", "topic": "relative pronoun whose"}, {"id": "M105", "type": "grammar", "q": "This is the small village ______ my grandparents grew up.", "options": ["which", "what", "where", "when"], "answer": 2, "explain": "句意：這就是我祖父母長大的小村莊。先行詞 village 為地點，且關係子句 my grandparents grew up 結構完整（grow up 為不及物動詞），須用關係副詞 where（= in which）。(A) which 須在子句中當主詞或受詞，或寫成 in which；(B) what 前面不可有先行詞；(D) when 用於表時間的先行詞。故選 (C)。", "level": "B1", "topic": "relative adverb where"}, {"id": "M106", "type": "grammar", "q": "______ his homework, Kevin went out to play basketball with his friends.", "options": ["Having finished", "Finished", "To finish", "Being finished"], "answer": 0, "explain": "句意：寫完功課後，Kevin 出去和朋友打籃球。主詞 Kevin 主動「完成」功課，且此動作發生在「出去打球」之前，用完成式分詞構句 Having finished（= After he had finished）。(B) Finished 為過去分詞，表被動，語意變成 Kevin 被完成；(C) To finish 表目的「為了完成功課」，與出去打球矛盾；(D) Being finished 也是被動。故選 (A)。", "level": "B2", "topic": "participle clause"}, {"id": "M107", "type": "grammar", "q": "All the students are looking forward to ______ the science museum next Friday.", "options": ["visit", "visited", "be visiting", "visiting"], "answer": 3, "explain": "句意：所有學生都很期待下週五參觀科學博物館。look forward to「期待」中的 to 是介系詞，後面須接名詞或動名詞，故用 visiting。(A) visit 為原形動詞；(B) visited 為過去式／過去分詞；(C) be visiting 不能接在介系詞之後。故選 (D)。", "level": "B1", "topic": "gerund after preposition"}, {"id": "M108", "type": "grammar", "q": "I clearly remember ______ the door before I left, but now it is open. Someone must have opened it.", "options": ["to lock", "locking", "lock", "to have been locked"], "answer": 1, "explain": "句意：我清楚記得出門前有鎖門，但現在門卻開著，一定有人打開過。remember + V-ing 表示「記得做過某事」（已發生）；remember + to V 表示「記得要去做某事」（尚未做）。本句指已鎖過門，故用 locking。(A) to lock 表「記得要去鎖」，與句意不符；(C) lock 原形不能直接接在 remember 後；(D) 為被動，主詞 I 不是被鎖的對象。故選 (B)。", "level": "B2", "topic": "gerund vs infinitive"}, {"id": "M109", "type": "grammar", "q": "______ it was raining heavily, the baseball game was not canceled.", "options": ["Although", "Despite", "Because", "In spite of"], "answer": 0, "explain": "句意：雖然雨下得很大，棒球比賽並沒有取消。空格後接完整子句 it was raining heavily，且前後語意相反，須用讓步連接詞 Although。(B) Despite 與 (D) In spite of 為介系詞（片語），後面要接名詞或動名詞，不能接子句；(C) Because 表原因，語意不合。故選 (A)。", "level": "B1", "topic": "although vs despite"}, {"id": "M110", "type": "grammar", "q": "You won't be allowed to take the exam ______ you bring your student ID card.", "options": ["if", "because", "unless", "so that"], "answer": 2, "explain": "句意：除非你帶學生證，否則不能參加考試。unless「除非」= if...not。(A) if 語意變成「如果帶了學生證就不能考試」，不合理；(B) because「因為帶了學生證所以不能考」，不合理；(D) so that 表目的「以便」，語意不合。故選 (C)。", "level": "B1", "topic": "conjunction unless"}, {"id": "M111", "type": "grammar", "q": "Nobody knows ______ the typhoon will hit Taiwan or turn north.", "options": ["that", "what", "which", "whether"], "answer": 3, "explain": "句意：沒有人知道颱風會侵襲台灣還是轉向北方。名詞子句表「是否」，且後面有 or 搭配，用 whether...or「是……還是……」。(A) that 引導的名詞子句表陳述事實，沒有「是否」之意；(B) what 與 (C) which 須在子句中當主詞或受詞，但 the typhoon will hit Taiwan 已是完整子句。故選 (D)。", "level": "B2", "topic": "conjunction whether"}, {"id": "M112", "type": "grammar", "q": "The math test was ______ difficult that only three students passed it.", "options": ["such", "so", "very", "too"], "answer": 1, "explain": "句意：數學考試難到只有三位學生及格。so + 形容詞／副詞 + that 子句「如此……以致於……」。(A) such 後面須接名詞（如 such a difficult test that...）；(C) very 不能與 that 子句形成結果句型；(D) too 須搭配 to V（too...to...），不接 that 子句。故選 (B)。", "level": "B1", "topic": "so...that"}, {"id": "M113", "type": "grammar", "q": "Each of the students in my class ______ a different hobby.", "options": ["have", "are having", "has", "having"], "answer": 2, "explain": "句意：我們班上每位學生都有不同的嗜好。Each of + 複數名詞作主詞時，真正主詞是 each，視為單數，動詞用 has。(A) have 為複數動詞；(B) are having 為複數且 have 表「擁有」時不用進行式；(D) having 不是限定動詞，句子會缺少主要動詞。故選 (C)。", "level": "B1", "topic": "subject-verb agreement"}, {"id": "M114", "type": "grammar", "q": "The more you practice speaking English, ______ you will become.", "options": ["the more confident", "more confident", "the most confident", "most confident"], "answer": 0, "explain": "句意：你越常練習說英文，就會變得越有自信。「the + 比較級..., the + 比較級...」表「越……就越……」，後半句也須用 the + 比較級，故為 the more confident。(B) 少了 the；(C) 與 (D) 為最高級，不符合此句型。故選 (A)。", "level": "B2", "topic": "double comparative"}, {"id": "M115", "type": "grammar", "q": "If I ______ a million dollars, I would travel around the world with my family.", "options": ["have", "will have", "had had", "had"], "answer": 3, "explain": "句意：如果我有一百萬美元，我會和家人環遊世界。主要子句為 would + 原形動詞，表示與現在事實相反的假設，if 子句用過去式 had。(A) have 用於可能成真的條件句（主句配 will）；(B) will have 不能用在 if 條件子句中；(C) had had 用於與過去事實相反的假設，主句須為 would have p.p.。故選 (D)。", "level": "B1", "topic": "second conditional"}, {"id": "M116", "type": "grammar", "q": "If Amy had left home earlier, she ______ the bus to school.", "options": ["would not miss", "would not have missed", "will not miss", "did not miss"], "answer": 1, "explain": "句意：如果 Amy 早點出門，她就不會錯過上學的公車了。if 子句用過去完成式 had left，表示與過去事實相反，主要子句用 would + have + p.p.，故為 would not have missed。(A) would not miss 用於與現在事實相反；(C) will not miss 用於可能成真的條件句；(D) did not miss 為一般過去式，不構成假設語氣。故選 (B)。", "level": "B2", "topic": "third conditional"}, {"id": "M117", "type": "grammar", "q": "I failed the English test yesterday. I wish I ______ harder last week.", "options": ["had studied", "studied", "would study", "have studied"], "answer": 0, "explain": "句意：我昨天英文考試不及格，真希望上週有更用功。wish 後接與過去事實相反的願望（last week 已過去，事實上沒有用功），子句用過去完成式 had studied。(B) studied 表與現在事實相反；(C) would study 表希望未來情況改變；(D) have studied 現在完成式不能用於 wish 的假設語氣。故選 (A)。", "level": "B2", "topic": "wish"}, {"id": "M118", "type": "grammar", "q": "You look really tired. You ______ to bed so late last night.", "options": ["must not go", "should not go", "should not have gone", "cannot have gone"], "answer": 2, "explain": "句意：你看起來好累，昨晚不應該那麼晚睡的。should not have + p.p. 表示「過去不該做某事（但卻做了）」，帶有責備或後悔之意。(A) must not go 與 (B) should not go 指現在或未來，不能搭配 last night；(D) cannot have gone 表「不可能已經……」的推測，與「你看起來很累」矛盾。故選 (C)。", "level": "B2", "topic": "modal + have p.p."}, {"id": "M119", "type": "grammar", "q": "Not until the teacher came into the classroom ______ talking.", "options": ["the students stopped", "the students did stop", "stopped the students", "did the students stop"], "answer": 3, "explain": "句意：直到老師走進教室，學生們才停止講話。Not until... 置於句首時，主要子句須倒裝，形式為「助動詞 + 主詞 + 原形動詞」，即 did the students stop。(A) 與 (B) 都是一般語序，沒有倒裝；(C) stopped the students 語序錯誤，語意也變成「使學生停下」。故選 (D)。", "level": "B2", "topic": "inversion not until"}, {"id": "M120", "type": "grammar", "q": "Hardly ______ the house when it started to rain.", "options": ["we had left", "had we left", "we left", "did we leave"], "answer": 1, "explain": "句意：我們一離開家就開始下雨了。Hardly... when...「一……就……」，Hardly 置於句首時須倒裝，且 Hardly 子句用過去完成式、when 子句用過去式，故為 had we left。(A) we had left 與 (C) we left 沒有倒裝；(D) did we leave 雖倒裝但時態錯誤，此句型 Hardly 子句須用過去完成式。故選 (B)。", "level": "B2", "topic": "inversion hardly...when"}, {"id": "M121", "type": "grammar", "q": "My little brother is very interested ______ collecting old coins.", "options": ["on", "at", "in", "with"], "answer": 2, "explain": "句意：我弟弟對收集舊硬幣很有興趣。be interested in + N／V-ing「對……有興趣」為固定搭配。(A) on、(B) at、(D) with 都不是此片語所用的介系詞。故選 (C)。", "level": "B1", "topic": "prepositions"}, {"id": "M122", "type": "grammar", "q": "I asked two of my friends to help me with my science project, but ______ of them was free on Sunday.", "options": ["neither", "none", "both", "either"], "answer": 0, "explain": "句意：我請兩位朋友幫忙做科展，但他們兩個週日都沒空。對象是「兩個」人，表示「兩者都不」用 neither，neither of + 複數名詞後接單數動詞 was。(B) none 用於三者以上；(C) both 須接複數動詞 were，且與 but 的轉折語意不合；(D) either 表「兩者之一（有空）」，與 but 的語意矛盾。故選 (A)。", "level": "B1", "topic": "determiners"}, {"id": "M123", "type": "grammar", "q": "Let's take a short break and get something to drink, ______?", "options": ["will you", "shall we", "don't we", "won't you"], "answer": 1, "explain": "句意：我們休息一下，去買點喝的，好嗎？以 Let's 開頭的祈使句（包含說話者自己），附加問句用 shall we。(A) will you 與 (D) won't you 用於一般祈使句（如 Close the door, will you?）；(C) don't we 不能用於 Let's 句型。故選 (B)。", "level": "B1", "topic": "question tags"}, {"id": "M124", "type": "grammar", "q": "Jason hardly ever eats breakfast before school, ______?", "options": ["doesn't he", "isn't he", "is he", "does he"], "answer": 3, "explain": "句意：Jason 上學前幾乎從不吃早餐，對吧？hardly ever「幾乎從不」為否定副詞，主要子句視為否定，附加問句須用肯定；eats 為一般動詞現在式，助動詞用 does，故為 does he。(A) doesn't he 為否定，誤把主句當成肯定；(B) isn't he 與 (C) is he 助動詞錯誤，主句沒有 be 動詞。故選 (D)。", "level": "B2", "topic": "question tags"}, {"id": "M125", "type": "grammar", "q": "By the time you get to the station tomorrow morning, the first train ______.", "options": ["will have left", "has left", "had left", "leaves"], "answer": 0, "explain": "句意：等你明天早上到車站時，第一班火車早已開走了。By the time + 現在式（表未來），主要子句用未來完成式 will have p.p.，表示「到未來某時之前某事已經完成」。(B) has left 現在完成式不能表示未來某時已完成；(C) had left 用於 By the time + 過去式；(D) leaves 現在式無法表達「在你到之前就已開走」。故選 (A)。", "level": "B2", "topic": "future perfect"}, {"id": "M126", "type": "grammar", "q": "While I ______ dinner, the lights suddenly went out.", "options": ["cook", "have cooked", "was cooking", "am cooking"], "answer": 2, "explain": "句意：我正在煮晚餐時，燈突然熄了。while 引導的子句表示過去某時「正在進行」的動作，被另一個過去的短暫動作（燈熄了）打斷，用過去進行式 was cooking。(A) cook 與 (D) am cooking 為現在時態，與 went out 不符；(B) have cooked 現在完成式不能描述過去特定事件。故選 (C)。", "level": "B1", "topic": "past continuous"}, {"id": "M127", "type": "grammar", "q": "All reports ______ to the teacher by this Friday.", "options": ["must hand in", "must handing in", "must be handing in", "must be handed in"], "answer": 3, "explain": "句意：所有報告必須在本週五前交給老師。報告是「被繳交」的，須用被動語態；情態助動詞的被動形式為 must + be + p.p.，故為 must be handed in。(A) must hand in 為主動，語意變成報告自己去繳交；(B) 情態助動詞後不能接 V-ing；(C) must be handing in 為主動進行式，語意不合。故選 (D)。", "level": "B1", "topic": "modal passive"}, {"id": "M128", "type": "grammar", "q": "Lisa's bike was broken, so she had it ______ at the shop near her house.", "options": ["repair", "repaired", "repairing", "to repair"], "answer": 1, "explain": "句意：Lisa 的腳踏車壞了，所以她拿到家附近的店去修理。使役動詞 have + 物 + p.p. 表示「請人把某物……」，腳踏車是「被修理」的，用過去分詞 repaired。(A) repair 原形用於受詞是「人」的主動結構（have someone repair it）；(C) repairing 表示受詞主動進行動作；(D) 使役動詞 have 後不接 to V。故選 (B)。", "level": "B2", "topic": "causative have"}, {"id": "M129", "type": "grammar", "q": "Having lived in Taipei for five years, Emma is used to ______ the MRT every day.", "options": ["take", "took", "taking", "be taken"], "answer": 2, "explain": "句意：在台北住了五年，Emma 已經習慣每天搭捷運。be used to + V-ing／N「習慣於……」，其中 to 是介系詞，後接動名詞 taking。(A) take 原形用於 used to V「過去常常」或 be used to V「被用來……」，皆不合句意；(B) took 為過去式；(D) be taken 為被動，語意不合。故選 (C)。", "level": "B2", "topic": "be used to"}, {"id": "M130", "type": "grammar", "q": "Tom forgot his mother's birthday, ______ made her very upset.", "options": ["which", "that", "what", "it"], "answer": 0, "explain": "句意：Tom 忘了媽媽的生日，這讓她很難過。逗點後的非限定關係子句可用 which 代替前面整個句子（忘了生日這件事），並在子句中當主詞。(B) that 不能用於逗點後的非限定關係子句；(C) what 前面不可有先行詞；(D) it 是代名詞，用逗點連接兩個獨立子句會形成錯誤句（run-on sentence）。故選 (A)。", "level": "B2", "topic": "non-defining which"}, {"id": "M131", "type": "grammar", "q": "Peter is not old ______ to get a driver's license yet.", "options": ["too", "enough", "so", "very"], "answer": 1, "explain": "句意：Peter 年紀還不夠大，還不能考駕照。形容詞 + enough + to V「夠……可以……」，enough 放在形容詞 old 之後。(A) too 須放在形容詞之前（too young to...）；(C) so 須搭配 that 子句；(D) very 不能與 to V 形成此句型。故選 (B)。", "level": "B1", "topic": "adjective + enough"}, {"id": "M132", "type": "grammar", "q": "Taipei 101 is one of the ______ in the world.", "options": ["tallest building", "taller buildings", "most tall buildings", "tallest buildings"], "answer": 3, "explain": "句意：台北101是世界上最高的建築之一。one of the + 最高級 + 複數名詞「最……的……之一」，tall 的最高級為 tallest，名詞須用複數 buildings。(A) tallest building 的名詞為單數；(B) taller 為比較級；(C) most tall 為錯誤的最高級形式。故選 (D)。", "level": "B1", "topic": "superlatives"}, {"id": "M133", "type": "grammar", "q": "It's already eleven o'clock. It's high time you ______ to bed.", "options": ["went", "go", "will go", "have gone"], "answer": 0, "explain": "句意：已經十一點了，你早該去睡覺了。It is (high) time + 主詞 + 過去式動詞，表示「早該做某事了（但還沒做）」，屬假設語氣，用過去式 went（也可說 It's time for you to go to bed）。(B) go 原形、(C) will go 未來式、(D) have gone 現在完成式都不合此句型。故選 (A)。", "level": "B2", "topic": "it's time + past"}, {"id": "M134", "type": "grammar", "q": "My sister spends at least two hours ______ online games every weekend.", "options": ["play", "to play", "playing", "played"], "answer": 2, "explain": "句意：我姊姊每個週末至少花兩小時玩線上遊戲。spend + 時間／金錢 + (in) V-ing「花時間或金錢做某事」，故用 playing。(A) play 原形、(B) to play 不定詞、(D) played 過去式都不合此句型。故選 (C)。", "level": "B1", "topic": "spend + V-ing"}, {"id": "M135", "type": "grammar", "q": "The students were made ______ the classroom after the party.", "options": ["clean", "to clean", "cleaning", "cleaned"], "answer": 1, "explain": "句意：派對結束後，學生們被要求打掃教室。使役動詞 make 主動時為 make + 人 + 原形動詞，但改成被動 be made 時須還原 to，成為 be made + to V，故用 to clean。(A) clean 原形只用於主動句（made the students clean...）；(C) cleaning 與 (D) cleaned 都不合此句型。故選 (B)。", "level": "B2", "topic": "passive of make"}, {"id": "M136", "type": "grammar", "q": "Not only ______ the piano, but she also writes her own songs.", "options": ["she plays", "plays she", "she does play", "does she play"], "answer": 3, "explain": "句意：她不僅會彈鋼琴，還會自己寫歌。Not only 置於句首時，該子句須倒裝：助動詞 + 主詞 + 原形動詞；現在式一般動詞借助 does，故為 does she play。(A) she plays 與 (C) she does play 沒有倒裝；(B) 一般動詞不能直接移到主詞前面倒裝。故選 (D)。", "level": "B2", "topic": "inversion not only"}, {"id": "M137", "type": "grammar", "q": "I will call you as soon as I ______ at the airport.", "options": ["arrive", "will arrive", "arrived", "am going to arrive"], "answer": 0, "explain": "句意：我一到機場就會打電話給你。表時間的副詞子句（as soon as、when、before、after 等）以現在式代替未來式，故用 arrive。(B) will arrive 與 (D) am going to arrive 不可用於時間副詞子句表未來；(C) arrived 為過去式，與主要子句 will call 不符。故選 (A)。", "level": "B1", "topic": "time clauses"}, {"id": "M138", "type": "grammar", "q": "The lecture was so long that many students in the hall felt ______.", "options": ["boring", "bored", "bore", "to bore"], "answer": 1, "explain": "句意：演講太長了，禮堂裡很多學生都覺得很無聊。描述「人」的感受用 -ed 形容詞，bored 表「感到無聊的」。(A) boring 表「令人無聊的」，用來描述事物（如 The lecture was boring）；(C) bore 為動詞或名詞；(D) to bore 不能接在 felt 後當補語。故選 (B)。", "level": "B1", "topic": "-ed/-ing adjectives"}, {"id": "M139", "type": "grammar", "q": "Hurry up! We have very ______ time before the concert begins.", "options": ["few", "many", "a few", "little"], "answer": 3, "explain": "句意：快一點！演唱會開始前我們只剩很少的時間了。time 為不可數名詞，表示「很少、幾乎沒有」用 little（very little）。(A) few、(B) many、(C) a few 都只能修飾可數名詞，且 Hurry up 暗示時間不夠，語意偏否定，須用 little。故選 (D)。", "level": "B1", "topic": "quantifiers"}, {"id": "M140", "type": "grammar", "q": "Either you or your brother ______ to wash the dishes tonight.", "options": ["have", "are", "has", "were"], "answer": 2, "explain": "句意：今晚不是你就是你弟弟要洗碗。Either A or B 作主詞時，動詞與最靠近的主詞 B 一致（就近原則）；B 為 your brother（第三人稱單數），故用 has to。(A) have 與 (B) are 為配合 you 或複數主詞的形式；(D) were 為過去式且不是第三人稱單數的形式，也與 tonight 不合。故選 (C)。", "level": "B2", "topic": "subject-verb agreement"}, {"id": "M141", "type": "grammar", "q": "Many teenagers prefer texting ______ talking on the phone.", "options": ["to", "than", "from", "for"], "answer": 0, "explain": "句意：許多青少年比較喜歡傳訊息，而不是講電話。prefer A to B「喜歡 A 勝過 B」，A、B 為名詞或動名詞，介系詞用 to。(B) than 用於比較級；prefer 若要接 than，須寫成 prefer to V rather than (V)，不能用在 prefer A ___ B 的句型；(C) from 與 (D) for 都不是此句型的搭配。故選 (A)。", "level": "B1", "topic": "prefer A to B"}, {"id": "M142", "type": "grammar", "q": "It looks like it's going to rain. You'd better ______ an umbrella with you.", "options": ["to take", "taking", "took", "take"], "answer": 3, "explain": "句意：看起來快下雨了，你最好帶把傘。had better（'d better）「最好……」後面接原形動詞，故為 take。(A) to take、(B) taking、(C) took 都不能接在 had better 之後。故選 (D)。", "level": "B1", "topic": "had better"}, {"id": "M143", "type": "grammar", "q": "When the clown fell off his chair, the audience couldn't help ______.", "options": ["to laugh", "laugh", "laughing", "laughed"], "answer": 2, "explain": "句意：小丑從椅子上摔下來時，觀眾忍不住大笑。can't／couldn't help + V-ing「忍不住……」，help 在此意為「避免」，後接動名詞 laughing。(A) to laugh 與 (B) laugh 不能直接接在 couldn't help 之後（另一種說法為 couldn't help but laugh）；(D) laughed 為過去式。故選 (C)。", "level": "B2", "topic": "can't help V-ing"}, {"id": "M144", "type": "grammar", "q": "I'm feeling a bit tired, so I would rather ______ home tonight than go to the party.", "options": ["to stay", "stay", "staying", "stayed"], "answer": 1, "explain": "句意：我有點累，所以今晚寧願待在家也不去派對。would rather + 原形動詞 + than + 原形動詞「寧願……而不願……」，與後面的 than go 對稱，故用 stay。(A) to stay 與 (C) staying 不能接在 would rather 之後；(D) stayed 用於 would rather + 另一個主詞 的假設語氣（如 I'd rather you stayed），此處主詞相同，不適用。故選 (B)。", "level": "B1", "topic": "would rather"}, {"id": "M145", "type": "grammar", "q": "Do you know the girl ______ next to the window? She is our new classmate.", "options": ["standing", "stood", "stands", "to stand"], "answer": 0, "explain": "句意：你認識站在窗邊的那個女孩嗎？她是我們的新同學。原句為 the girl who is standing next to the window，省略關係代名詞與 be 動詞後，主動用現在分詞 standing 修飾 girl。(B) stood 為過去分詞，表被動，且 stand 為不及物動詞；(C) stands 為限定動詞，句中已有主要動詞 know，不能再直接接；(D) to stand 表未來或目的，語意不合。故選 (A)。", "level": "B1", "topic": "reduced relative clause"}, {"id": "M146", "type": "grammar", "q": "Grandpa was sitting on the sofa with his arms ______, listening to his favorite music.", "options": ["folding", "fold", "folded", "to fold"], "answer": 2, "explain": "句意：爺爺雙臂交叉坐在沙發上，聽著他最喜歡的音樂。with + 受詞 + 分詞 表示附帶狀況；手臂是「被（爺爺）交叉起來」的，與 arms 為被動關係，用過去分詞 folded。(A) folding 表示手臂主動在摺疊，語意不合；(B) fold 原形與 (D) to fold 都不合此句型。故選 (C)。", "level": "B2", "topic": "with + O + participle"}, {"id": "M147", "type": "grammar", "q": "______ you need any help with your project, please feel free to contact me.", "options": ["Unless", "Had", "Were", "Should"], "answer": 3, "explain": "句意：如果你的專題需要任何幫忙，請隨時跟我聯絡。Should + 主詞 + 原形動詞 為省略 if 的倒裝條件句，= If you should need any help，表「萬一、如果需要」。(A) Unless「除非」語意相反；(B) Had 倒裝後須接 p.p.（Had you needed），表與過去事實相反；(C) Were 倒裝後須接名詞、形容詞或 to V（Were you to need），不能接原形動詞。故選 (D)。", "level": "B2", "topic": "inverted conditional"}, {"id": "M148", "type": "grammar", "q": "The number of students who walk to school ______ decreasing in recent years.", "options": ["have been", "has been", "are", "were"], "answer": 1, "explain": "句意：近年來走路上學的學生人數一直在減少。The number of + 複數名詞「……的數量」，主詞是 the number，視為單數；in recent years 表示從過去持續到現在，用現在完成進行式 has been decreasing。(A) have been 與 (C) are 為複數動詞（A number of + 複數名詞「許多」才接複數動詞）；(D) were 為過去式且為複數。故選 (B)。", "level": "B1", "topic": "subject-verb agreement"}, {"id": "M149", "type": "grammar", "q": "Ben ______ my email this afternoon. He has been on a plane without Internet access all day.", "options": ["can't have read", "must have read", "should have read", "needn't have read"], "answer": 0, "explain": "句意：Ben 今天下午不可能讀過我的電子郵件，他整天都在沒有網路的飛機上。can't have + p.p. 表示對過去的推測「不可能已經……」。(B) must have read 表「一定已經讀了」，與事實矛盾；(C) should have read 表「本來應該讀（卻沒讀）」，帶責備意味，但他無法上網，不合邏輯；(D) needn't have read 表「其實不必讀卻讀了」，表示他有讀，也與事實矛盾。故選 (A)。", "level": "B2", "topic": "modal deduction"}, {"id": "M150", "type": "grammar", "q": "Would you mind ______ the window? It's a little cold in here.", "options": ["close", "to close", "closing", "closed"], "answer": 2, "explain": "句意：你介意關一下窗戶嗎？這裡有點冷。mind 後面接動名詞，Would you mind + V-ing? 為禮貌的請求，故用 closing。(A) close 原形、(B) to close 不定詞、(D) closed 過去式都不能接在 mind 之後。故選 (C)。", "level": "B1", "topic": "mind + V-ing"}, {"id": "M151", "type": "grammar", "q": "My grandfather ______ his bike to work every day, but now he takes the MRT.", "options": ["rides", "used to ride", "is riding", "has ridden"], "answer": 1, "explain": "句意：我爺爺以前每天騎腳踏車上班，但現在他改搭捷運。used to + 原形動詞表示「過去常常…（現在已不再）」，與後句 but now 形成對比。(A) rides 現在式表示現在的習慣，與「現在搭捷運」矛盾；(C) is riding 現在進行式不合句意；(D) has ridden 現在完成式無法表達「過去的習慣，現在已改變」。故選 (B)。", "level": "B1", "topic": "used to"}, {"id": "M152", "type": "grammar", "q": "A new swimming pool ______ at our school next year, so students will be able to take swimming classes.", "options": ["builds", "is building", "has built", "will be built"], "answer": 3, "explain": "句意：我們學校明年將蓋一座新游泳池，屆時學生就能上游泳課了。游泳池是「被建造」，須用被動語態；next year 表示未來，故用未來式被動 will be built。(A) builds、(B) is building、(C) has built 都是主動語態，好像游泳池自己在蓋東西，不合理。故選 (D)。", "level": "B1", "topic": "future passive"}, {"id": "M153", "type": "grammar", "q": "I find ______ hard to wake up early on cold winter mornings.", "options": ["it", "that", "this", "what"], "answer": 0, "explain": "句意：我覺得在寒冷的冬天早上很難早起。「find + it + 形容詞 + to V」中，it 為虛受詞，代替後面真正的受詞 to wake up early...。(B) that、(C) this 不能當虛受詞來指後面的不定詞片語；(D) what 無法用在此句型。故選 (A)。", "level": "B2", "topic": "it as dummy object"}, {"id": "M154", "type": "grammar", "q": "To stay healthy, you should avoid ______ too many sugary drinks.", "options": ["drink", "to drink", "drinking", "to drinking"], "answer": 2, "explain": "句意：為了保持健康，你應該避免喝太多含糖飲料。avoid 後面須接動名詞 (V-ing)，即 avoid drinking。(A) drink 原形動詞、(B) to drink 不定詞都不能接在 avoid 之後；(D) to drinking 文法錯誤。故選 (C)。", "level": "B1", "topic": "avoid + V-ing"}, {"id": "M155", "type": "grammar", "q": "The streets are all wet this morning. It ______ heavily last night.", "options": ["must have rained", "should have rained", "can't have rained", "must rain"], "answer": 0, "explain": "句意：今天早上街道全都濕了，昨晚一定下了大雨。must have + p.p. 表示「對過去事情有把握的肯定推測」（過去一定…）。(B) should have rained 表示「過去本來應該…（卻沒有）」，語意不合；(C) can't have rained 表示「昨晚不可能下雨」，與街道濕了矛盾；(D) must rain 指現在或未來，無法搭配 last night。故選 (A)。", "level": "B2", "topic": "modal + have p.p."}, {"id": "M156", "type": "grammar", "q": "Write down my phone number ______ you get lost in the city.", "options": ["unless", "because", "although", "in case"], "answer": 3, "explain": "句意：把我的電話號碼寫下來，以防你在市區迷路。in case「以防萬一」，後接子句，表示預先做準備。(A) unless「除非」會變成「除非你迷路，否則把電話寫下來」，不合邏輯；(B) because「因為」用於已確定的原因，但迷路尚未發生；(C) although「雖然」表讓步，也不合語意。故選 (D)。", "level": "B1", "topic": "conjunction in case"}, {"id": "M157", "type": "grammar", "q": "______ that my friends were secretly planning a surprise party for me.", "options": ["Little I knew", "Little did I know", "Little I did know", "Little knew I"], "answer": 1, "explain": "句意：我完全不知道朋友們正偷偷幫我籌備一場驚喜派對。具否定意味的副詞 Little（完全不）放句首時，句子須倒裝，一般動詞用「助動詞 + 主詞 + 原形動詞」，即 Little did I know。(A) Little I knew、(C) Little I did know 都沒有倒裝；(D) Little knew I 直接把一般動詞移到主詞前，是錯誤的倒裝形式。故選 (B)。", "level": "B2", "topic": "inversion: little"}, {"id": "M158", "type": "grammar", "q": "Watching movies with friends ______ my favorite way to relax on weekends.", "options": ["are", "were", "is", "have"], "answer": 2, "explain": "句意：和朋友一起看電影是我週末最喜歡的放鬆方式。動名詞片語 Watching movies with friends 當主詞時，視為單數，動詞用 is。(A) are、(B) were 是複數動詞，誤把 movies 或 friends 當成主詞；(D) have 不合句意，此處須用 be 動詞連接主詞與補語。故選 (C)。", "level": "B1", "topic": "gerund subject agreement"}, {"id": "M159", "type": "grammar", "q": "______ what to say, Tina just smiled and nodded.", "options": ["Knowing not", "Not known", "Not to know", "Not knowing"], "answer": 3, "explain": "句意：因為不知道該說什麼，Tina 只是微笑點頭。此為分詞構句，原句為 Because she didn't know what to say...，主詞相同且為主動，否定的分詞構句要把 not 放在分詞前面，即 Not knowing。(A) Knowing not 否定詞位置錯誤；(B) Not known 為過去分詞，表被動，不合句意；(C) Not to know 為不定詞，不能表示原因。故選 (D)。", "level": "B2", "topic": "negative participle clause"}, {"id": "M160", "type": "grammar", "q": "Our new gym is twice ______ the old one, so the whole school can fit inside.", "options": ["as big as", "bigger as", "as bigger as", "the biggest of"], "answer": 0, "explain": "句意：我們新的體育館是舊的兩倍大，所以全校師生都容納得下。倍數比較用「倍數 + as + 形容詞原級 + as」，即 twice as big as。(B) bigger as 比較級不能接 as；(C) as bigger as 中間不能用比較級；(D) the biggest of 為最高級，不能接在倍數後比較兩者。故選 (A)。", "level": "B2", "topic": "multiples: twice as...as"}, {"id": "M161", "type": "grammar", "q": "Our school's sports day will be held ______ the morning of October 25.", "options": ["in", "at", "on", "by"], "answer": 2, "explain": "句意：我們學校的運動會將在 10 月 25 日早上舉行。一般說 in the morning，但指「特定某一天的早上」時要用 on，如 on the morning of October 25。(A) in 用於一般的早上、月份或年份；(B) at 用於時刻；(D) by 表「在…之前」，皆不合。故選 (C)。", "level": "B1", "topic": "prepositions of time"}, {"id": "M162", "type": "grammar", "q": "If I had gone to bed earlier last night, I ______ so sleepy now.", "options": ["won't feel", "wouldn't feel", "wouldn't have felt", "didn't feel"], "answer": 1, "explain": "句意：如果我昨晚早點睡，現在就不會這麼睏了。這是混合條件句：if 子句用 had + p.p. 表示與過去事實相反；主要子句有 now，表示與現在事實相反，須用 would + 原形動詞，即 wouldn't feel。(A) won't feel 為一般條件句的用法；(C) wouldn't have felt 表示與過去事實相反，與 now 衝突；(D) didn't feel 不能用在條件句的主要子句。故選 (B)。", "level": "B2", "topic": "mixed conditional"}, {"id": "M163", "type": "grammar", "q": "Your sister can speak Japanese, ______?", "options": ["doesn't she", "isn't she", "can she", "can't she"], "answer": 3, "explain": "句意：你姊姊會說日語，不是嗎？附加問句的助動詞須與前句一致，且「前肯後否」。前句用 can，故附加問句用 can't she。(A) doesn't she、(B) isn't she 助動詞錯誤；(C) can she 為肯定形式，不符合「前肯後否」。故選 (D)。", "level": "B1", "topic": "question tags"}, {"id": "M164", "type": "grammar", "q": "Many new students have difficulty ______ their way around the large campus.", "options": ["finding", "to find", "find", "found"], "answer": 0, "explain": "句意：許多新生在這個大校園裡很難找到路。have difficulty (in) + V-ing 表示「做…有困難」，故用 finding。(B) to find 不定詞、(C) find 原形動詞、(D) found 過去式都不能用在此句型。故選 (A)。", "level": "B1", "topic": "have difficulty + V-ing"}, {"id": "M165", "type": "grammar", "q": "I wish I ______ how to swim. Then I could join my friends at the beach.", "options": ["know", "have known", "knew", "will know"], "answer": 2, "explain": "句意：真希望我會游泳，那樣我就能和朋友一起去海邊玩了。wish 表示與現在事實相反的願望時，後面子句用過去式，故用 knew。(A) know 現在式不能表示與事實相反；(B) have known 時態錯誤；(D) will know 是未來式，wish 子句不用此形式。故選 (C)。", "level": "B2", "topic": "wish (present)"}, {"id": "M166", "type": "grammar", "q": "I still remember the day ______ I first met my best friend in junior high school.", "options": ["which", "when", "where", "what"], "answer": 1, "explain": "句意：我還記得在國中第一次遇見我最好朋友的那一天。先行詞 the day 表時間，且關係子句結構完整 (I first met my best friend)，須用關係副詞 when (= on which)。(A) which 須在子句中當主詞或受詞，但此子句不缺；(C) where 指地點；(D) what 不能接在先行詞之後。故選 (B)。", "level": "B1", "topic": "relative adverb when"}, {"id": "M167", "type": "grammar", "q": "It was ______ a hot day that my ice cream melted before I could finish it.", "options": ["such", "so", "too", "very"], "answer": 0, "explain": "句意：那天實在太熱了，我的冰淇淋還沒吃完就融化了。「such + a/an + 形容詞 + 名詞 + that 子句」表示「如此…以致於…」，空格後是名詞片語 a hot day，故用 such。(B) so 後面直接接形容詞，須寫成 so hot a day 才正確；(C) too 常與 to V 連用 (too...to...)；(D) very 無法與 that 子句搭配形成此句型。故選 (A)。", "level": "B1", "topic": "such...that"}, {"id": "M168", "type": "grammar", "q": "My parents won't let me ______ out after ten o'clock on school nights.", "options": ["going", "to go", "gone", "go"], "answer": 3, "explain": "句意：隔天要上學的晚上，我爸媽不准我十點後出門。使役動詞 let 的用法為「let + 受詞 + 原形動詞」，故用 go。(A) going 動名詞、(B) to go 不定詞、(C) gone 過去分詞都不能接在 let + 受詞之後。故選 (D)。", "level": "B1", "topic": "let + O + V"}, {"id": "M169", "type": "grammar", "q": "I have two brothers. One is a nurse, and ______ is a police officer.", "options": ["another", "other", "the other", "others"], "answer": 2, "explain": "句意：我有兩個兄弟，一個是護理師，另一個是警察。兩者之中，一個用 one，「另一個」用 the other。(A) another 用於三者以上中的「另一個」；(B) other 為形容詞，後面須接名詞；(D) others 為複數，指「其他的人／物」，與單數動詞 is 不合。故選 (C)。", "level": "B1", "topic": "one...the other"}, {"id": "M170", "type": "grammar", "q": "My family ______ to Yilan two years ago, and we really love living there.", "options": ["moves", "moved", "has moved", "have moved"], "answer": 1, "explain": "句意：我們家兩年前搬到宜蘭，我們真的很喜歡住在那裡。ago 表示過去的時間點，須用過去簡單式 moved。(A) moves 現在式不能搭配 two years ago；(C) has moved、(D) have moved 為現在完成式，不能與 ago 這類明確的過去時間連用。故選 (B)。", "level": "B1", "topic": "simple past with ago"}, {"id": "M171", "type": "grammar", "q": "Falling down on the stage in front of the whole school was really ______ for Amy.", "options": ["embarrassing", "embarrassed", "embarrass", "embarrassment"], "answer": 0, "explain": "句意：在全校面前跌倒在舞台上，對 Amy 來說真的很令人尷尬。主詞是「在台上跌倒」這件事，事物「令人感到…」用現在分詞 embarrassing。(B) embarrassed 表示「人感到尷尬」，主詞須為人；(C) embarrass 是動詞原形；(D) embarrassment 是名詞，不能被 really 修飾當補語。故選 (A)。", "level": "B1", "topic": "participial adjectives"}, {"id": "M172", "type": "grammar", "q": "Rarely ______ late for school; he usually arrives before seven-thirty.", "options": ["Ben is", "Ben was", "is Ben", "does Ben"], "answer": 2, "explain": "句意：Ben 很少上學遲到，他通常七點半前就到了。具否定意味的副詞 Rarely（很少）放句首時，句子須倒裝；句中動詞為 be 動詞，直接將 is 移到主詞前，即 is Ben。(A) Ben is、(B) Ben was 都沒有倒裝，且 (B) 的時態與 usually arrives 不符；(D) does Ben 後面缺少動詞，late 是形容詞，須搭配 be 動詞。故選 (C)。", "level": "B2", "topic": "inversion: rarely"}, {"id": "M173", "type": "grammar", "q": "______ the heavy traffic, we arrived at the concert hall on time.", "options": ["Although", "Because of", "Unless", "Despite"], "answer": 3, "explain": "句意：儘管交通很壅塞，我們還是準時抵達音樂廳。空格後是名詞片語 the heavy traffic，且前後語意相反，須用介系詞 Despite「儘管」。(A) Although 是連接詞，後面須接子句；(B) Because of「因為」語意不合；(C) Unless「除非」是連接詞，後接子句，語意也不合。故選 (D)。", "level": "B2", "topic": "despite vs although"}, {"id": "M174", "type": "grammar", "q": "Ten thousand dollars ______ a lot of money for a high school student.", "options": ["are", "is", "were", "have"], "answer": 1, "explain": "句意：一萬元對高中生來說是一大筆錢。表示金額、時間、距離的複數名詞被視為「一個整體」時，當單數，動詞用 is。(A) are、(C) were 為複數動詞；(D) have 不合句意，此處須用 be 動詞連接補語 a lot of money。故選 (B)。", "level": "B2", "topic": "agreement with amounts"}, {"id": "M175", "type": "grammar", "q": "The friend ______ I traveled to Japan last summer is moving to Canada next month.", "options": ["with whom", "whom", "with who", "which"], "answer": 0, "explain": "句意：去年夏天和我一起去日本旅行的那位朋友，下個月要搬去加拿大了。原句為 I traveled to Japan with the friend，介系詞 with 移到關係代名詞前時，須用受格 whom，即 with whom。(B) whom 單獨使用時，句中缺少介系詞 with；(C) 介系詞後面不能接主格 who；(D) which 用於事物，不能指人。故選 (A)。", "level": "B2", "topic": "preposition + whom"}, {"id": "M176", "type": "grammar", "q": "After a long discussion, the class decided ______ a food stand at the school fair.", "options": ["run", "running", "to run", "to running"], "answer": 2, "explain": "句意：經過長時間的討論，全班決定在校慶園遊會上擺一個小吃攤。decide 後面接不定詞 to V，表示「決定做某事」，故用 to run。(A) run 原形、(B) running 動名詞都不能接在 decide 之後；(D) to running 文法錯誤。故選 (C)。", "level": "B1", "topic": "decide + to V"}, {"id": "M177", "type": "grammar", "q": "This summer was not as ______ as last summer; we hardly needed to turn on the air conditioner.", "options": ["hotter", "hot", "hottest", "more hot"], "answer": 1, "explain": "句意：今年夏天沒有去年夏天那麼熱，我們幾乎不需要開冷氣。「not as + 形容詞原級 + as」表示「不如…」，as...as 中間須用原級 hot。(A) hotter 為比較級，(D) more hot 為錯誤的比較級形式；(C) hottest 為最高級，都不能放在 as...as 中間。故選 (B)。", "level": "B1", "topic": "as...as comparison"}, {"id": "M178", "type": "grammar", "q": "Why didn't you tell me you needed a ride yesterday? I ______ you to the station.", "options": ["could drive", "must have driven", "can't have driven", "could have driven"], "answer": 3, "explain": "句意：你昨天怎麼沒跟我說你需要人載？我本來可以開車載你去車站的。could have + p.p. 表示「過去本來可以做（但實際上沒做）」。(A) could drive 指現在或未來的能力、可能，不能用於昨天已過去的情境；(B) must have driven 表示「過去一定載過了」，與事實不符；(C) can't have driven 表示「過去不可能載」，是推測用法，不合句意。故選 (D)。", "level": "B2", "topic": "could have p.p."}, {"id": "M179", "type": "grammar", "q": "My sister is very proud ______ the photography award she won last month.", "options": ["of", "for", "with", "at"], "answer": 0, "explain": "句意：我姊姊對她上個月得到的攝影獎感到非常驕傲。be proud of「以…為榮」為固定搭配。(B) for、(C) with、(D) at 都不能與 proud 搭配表達此義。故選 (A)。", "level": "B1", "topic": "adjective + preposition"}, {"id": "M180", "type": "grammar", "q": "The smartphone ______ by this company last month has already sold over one million units.", "options": ["releasing", "releases", "released", "was released"], "answer": 2, "explain": "句意：這家公司上個月推出的智慧型手機已經賣出超過一百萬支。手機是「被推出」，用過去分詞 released 修飾前面的名詞 (= which was released)。(A) releasing 現在分詞表主動，不合句意；(B) releases、(D) was released 是動詞，但句子已有主要動詞 has sold，不能再出現另一個動詞。故選 (C)。", "level": "B2", "topic": "past participle modifier"}, {"id": "M181", "type": "grammar", "q": "______ you, I would apologize to her as soon as possible.", "options": ["If I am", "I were", "Was I", "Were I"], "answer": 3, "explain": "句意：如果我是你，我會盡快向她道歉。與現在事實相反的假設 If I were you 可省略 if，將 were 移到主詞前倒裝成 Were I you。(A) If I am 是一般條件句，不能表示「我是你」這種不可能的假設；(B) I were 缺少連接詞也未倒裝；(C) Was I 不是此句型的正確形式，須用 were。故選 (D)。", "level": "B2", "topic": "inverted conditional"}, {"id": "M182", "type": "grammar", "q": "Please speak louder ______ everyone in the back of the room can hear you.", "options": ["so that", "even if", "as if", "in case of"], "answer": 0, "explain": "句意：請說大聲一點，好讓教室後面的每個人都聽得到。so that + 子句表示目的「以便、好讓」，常與 can / could 連用。(B) even if「即使」表讓步；(C) as if「彷彿」表示狀態；(D) in case of 是介系詞片語，後面須接名詞，不能接子句。故選 (A)。", "level": "B1", "topic": "so that (purpose)"}, {"id": "M183", "type": "grammar", "q": "Kevin forgot his calculator, so I lent him ______.", "options": ["my", "mine", "me", "myself"], "answer": 1, "explain": "句意：Kevin 忘了帶計算機，所以我把我的借給他。空格是 lent him 後的直接受詞，指「我的計算機」，須用所有格代名詞 mine (= my calculator)。(A) my 是所有格形容詞，後面必須接名詞；(C) me 會變成「把我借給他」，不合理；(D) myself 反身代名詞也不合語意。故選 (B)。", "level": "B1", "topic": "possessive pronouns"}, {"id": "M184", "type": "grammar", "q": "______ surprised me most was that the little girl could play the violin so well.", "options": ["That", "Which", "What", "It"], "answer": 2, "explain": "句意：最讓我驚訝的是，那個小女孩小提琴拉得那麼好。空格引導名詞子句當整句主詞，且子句中缺主詞 (___ surprised me most)，須用複合關係代名詞 What (= the thing that)。(A) That 引導名詞子句時，子句必須完整，不能缺主詞；(B) Which 沒有先行詞，不能這樣使用；(D) It 會造成一句中有兩個動詞 (surprised, was)，文法錯誤。故選 (C)。", "level": "B2", "topic": "noun clause with what"}, {"id": "M185", "type": "grammar", "q": "It is no use ______ over spilt milk.", "options": ["cry", "crying", "to crying", "cried"], "answer": 1, "explain": "句意：為打翻的牛奶哭泣是沒有用的（覆水難收）。It is no use + V-ing 為固定句型，表示「做…是沒有用的」，故用 crying。(A) cry 原形、(D) cried 過去式不能用在此句型；(C) to crying 文法錯誤。故選 (B)。", "level": "B2", "topic": "it is no use + V-ing"}, {"id": "M186", "type": "grammar", "q": "The road in front of our school ______ right now, so we have to take a different way home.", "options": ["is repairing", "has repaired", "repairs", "is being repaired"], "answer": 3, "explain": "句意：學校前面的道路現在正在整修，所以我們得走別條路回家。道路是「被修理」，且 right now 表示動作正在進行，須用現在進行式被動「is being + p.p.」。(A) is repairing、(B) has repaired、(C) repairs 都是主動語態，好像道路自己在修東西，不合理。故選 (D)。", "level": "B2", "topic": "present continuous passive"}, {"id": "M187", "type": "grammar", "q": "You can borrow my notebook ______ you return it to me by Friday.", "options": ["unless", "though", "as long as", "whether"], "answer": 2, "explain": "句意：只要你在星期五前還我，就可以借我的筆記本。as long as「只要」表條件。(A) unless「除非」會變成「如果你不在星期五前還我，就可以借」，語意相反；(B) though「雖然」表讓步；(D) whether「是否」不能引導此條件子句。故選 (C)。", "level": "B1", "topic": "conjunction as long as"}, {"id": "M188", "type": "grammar", "q": "The new MRT line makes it ______ easier for people to travel between the two cities.", "options": ["much", "very", "more", "most"], "answer": 0, "explain": "句意：新的捷運線讓兩座城市之間的往來方便多了。修飾比較級 easier 要用 much、a lot、even、far 等副詞，表示「…得多」。(B) very 不能修飾比較級；(C) more easier 為雙重比較級，錯誤；(D) most 為最高級用字，不能修飾比較級。故選 (A)。", "level": "B1", "topic": "modifying comparatives"}, {"id": "M189", "type": "grammar", "q": "There's a math test tomorrow, ______?", "options": ["is it", "isn't there", "isn't it", "is there"], "answer": 1, "explain": "句意：明天有數學考試，對吧？There is 句型的附加問句要用 there 當主詞，且「前肯後否」，故用 isn't there。(A) is it、(C) isn't it 主詞錯誤，不能用 it；(D) is there 為肯定形式，不符合「前肯後否」。故選 (B)。", "level": "B1", "topic": "question tags"}, {"id": "M190", "type": "grammar", "q": "The teacher, as well as her students, ______ excited about the field trip to Tainan.", "options": ["are", "were", "have", "is"], "answer": 3, "explain": "句意：老師和她的學生們都對台南的校外教學感到很興奮。A as well as B 當主詞時，動詞須與前面的 A 一致；A 為 The teacher（單數），故用 is。(A) are、(B) were 為複數動詞，誤把 students 當成主詞；(C) have 不合句意，excited 為形容詞，須搭配 be 動詞。故選 (D)。", "level": "B2", "topic": "as well as agreement"}, {"id": "M191", "type": "grammar", "q": "The box is too heavy for me ______. Can you give me a hand?", "options": ["carry", "carrying", "to carry", "carried"], "answer": 2, "explain": "句意：這個箱子太重了，我搬不動，你可以幫我一下嗎？「too + 形容詞 + (for 人) + to V」表示「太…而不能…」，故用 to carry。(A) carry 原形、(B) carrying 動名詞、(D) carried 過去式／過去分詞都不能用在此句型。故選 (C)。", "level": "B1", "topic": "too...to"}, {"id": "M192", "type": "grammar", "q": "I ______ for the bus for forty minutes, and it still hasn't come.", "options": ["have been waiting", "was waiting", "wait", "had waited"], "answer": 0, "explain": "句意：我已經等公車等了四十分鐘，公車還是沒來。for + 一段時間，且動作從過去持續到現在、仍在進行 (still hasn't come)，用現在完成進行式 have been waiting。(B) was waiting 過去進行式只表示過去某時正在進行；(C) wait 現在式不能搭配 for forty minutes 表持續；(D) had waited 過去完成式與 still hasn't come 的現在時間不合。故選 (A)。", "level": "B2", "topic": "present perfect continuous"}, {"id": "M193", "type": "grammar", "q": "The girl ______ won first prize in the speech contest is my cousin.", "options": ["which", "whom", "whose", "who"], "answer": 3, "explain": "句意：在演講比賽中得到第一名的那個女孩是我表妹。先行詞 the girl 是人，且關係子句中缺主詞 (___ won first prize)，須用主格關係代名詞 who。(A) which 用於事物；(B) whom 是受格，不能當主詞；(C) whose 為所有格，後面須接名詞。故選 (D)。", "level": "B1", "topic": "relative pronoun who"}, {"id": "M194", "type": "grammar", "q": "______ in simple English, this novel is easy for beginners to read.", "options": ["Writing", "Written", "To write", "Having written"], "answer": 1, "explain": "句意：這本小說是用簡單的英文寫成的，對初學者來說很容易閱讀。主詞 this novel 是「被寫」，分詞構句表被動須用過去分詞 Written (= Because it is written...)。(A) Writing、(D) Having written 表主動，好像小說自己在寫作；(C) To write 表目的，不合句意。故選 (B)。", "level": "B2", "topic": "participle clause (passive)"}, {"id": "M195", "type": "grammar", "q": "Life in the countryside is quite different ______ life in the city.", "options": ["with", "for", "from", "of"], "answer": 2, "explain": "句意：鄉村的生活和城市的生活很不一樣。be different from「與…不同」為固定搭配。(A) with、(B) for、(D) of 都不能與 different 搭配表達此義。故選 (C)。", "level": "B1", "topic": "different from"}, {"id": "M196", "type": "grammar", "q": "Jenny and her sister often share clothes and help ______ with homework.", "options": ["each other", "themselves", "herself", "theirs"], "answer": 0, "explain": "句意：Jenny 和她妹妹常常共穿衣服，也會互相幫忙寫功課。each other 表示「彼此、互相」，符合兩人互相幫忙的語意。(B) themselves 為反身代名詞，help themselves 意為「自行取用」或「幫自己」，不合語意；(C) herself 為單數，與兩人的主詞不一致；(D) theirs 為所有格代名詞，不能這樣當 help 的受詞。故選 (A)。", "level": "B1", "topic": "reciprocal pronoun"}, {"id": "M197", "type": "grammar", "q": "Jack talks ______ he knew everything about computers, but he actually knows very little.", "options": ["even if", "as if", "so that", "unless"], "answer": 1, "explain": "句意：Jack 說起話來彷彿他對電腦無所不知，但其實他懂得很少。as if「彷彿、好像」，後接與事實相反的假設時用過去式 (knew)。(A) even if「即使」表讓步；(C) so that「以便」表目的；(D) unless「除非」表條件，都不合語意。故選 (B)。", "level": "B2", "topic": "as if"}, {"id": "M198", "type": "grammar", "q": "Don't forget ______ off the lights when you leave the classroom.", "options": ["turning", "turn", "to turn", "turned"], "answer": 2, "explain": "句意：離開教室時別忘了關燈。forget + to V 表示「忘記去做（尚未做的事）」，forget + V-ing 表示「忘記曾做過某事」。此處是提醒對方待會要關燈，故用 to turn。(A) turning 表示「忘記已經關過燈」，不合語意；(B) turn 原形、(D) turned 過去式都不能接在 forget 之後。故選 (C)。", "level": "B1", "topic": "forget to V vs V-ing"}, {"id": "M199", "type": "grammar", "q": "So excited ______ about the trip that she couldn't fall asleep.", "options": ["was she", "she was", "did she", "she did"], "answer": 0, "explain": "句意：她對這趟旅行太興奮了，以致於睡不著。原句為 She was so excited about the trip that...，「So + 形容詞」移到句首時須倒裝成「be 動詞 + 主詞」，即 was she。(B) she was 未倒裝；(C) did she、(D) she did 誤用助動詞 did，句中動詞應為 be 動詞 was。故選 (A)。", "level": "B2", "topic": "inversion: so...that"}, {"id": "M200", "type": "grammar", "q": "This is the best movie ______ I have ever seen.", "options": ["what", "whom", "who", "that"], "answer": 3, "explain": "句意：這是我看過最好看的電影。先行詞被最高級 (the best) 修飾時，關係代名詞通常用 that。(A) what 不能接在先行詞之後；(B) whom、(C) who 用於指人，不能指 movie。故選 (D)。", "level": "B1", "topic": "relative that after superlatives"}, {"id": "M201", "type": "dialogue", "q": "A: Excuse me, do you have this T-shirt in a larger size?\nB: ______\nA: Great. I'll try it on.", "options": ["Sorry, we don't accept credit cards.", "Let me check. Yes, here's a large.", "It's on the second floor, next to the elevator.", "You can return it within seven days."], "answer": 1, "explain": "A 詢問這件 T 恤有沒有大一點的尺寸，B 回答「我查一下，有，這件是 L 號」，A 接著說要試穿，前後連貫。(A) 抱歉，我們不收信用卡，與尺寸無關；(C) 在二樓電梯旁，答非所問；(D) 七天內可退貨，與詢問尺寸無關。故選 (B)。", "level": "B1", "topic": "shopping"}, {"id": "M202", "type": "dialogue", "q": "A: Are you ready to order, sir?\nB: ______\nA: Sure. Take your time. I'll come back in a few minutes.", "options": ["Yes, I'd like the beef noodles, please.", "The bill comes to 450 dollars.", "I'm afraid the kitchen is closed.", "Not yet. Could I have a few more minutes?"], "answer": 3, "explain": "服務生問是否準備好點餐，客人回答「還沒，可以再給我幾分鐘嗎？」，服務生才會說「沒問題，慢慢來，我幾分鐘後再過來」。(A) 已經點了牛肉麵，服務生不會說慢慢來；(B) 帳單金額是 450 元，應由服務生說；(C) 廚房已打烊，也應是店員的話。故選 (D)。", "level": "B1", "topic": "restaurant"}, {"id": "M203", "type": "dialogue", "q": "A: Hello. May I speak to Ms. Chen, please?\nB: ______\nA: Could you tell her that Kevin called? I'll call back later.", "options": ["I'm sorry, she's out at the moment.", "Speaking. How can I help you?", "I'm afraid you have the wrong number.", "Yes. I'll put you through right away."], "answer": 0, "explain": "A 要找陳小姐，B 說「抱歉，她現在不在」，所以 A 才請 B 轉告「Kevin 打過電話，我晚點再打」。(B) Speaking 表示「我就是」，A 不需再留言；(C) 打錯電話了，A 不會請對方轉告；(D) 我馬上幫你轉接，A 也不必留言。故選 (A)。", "level": "B1", "topic": "phone call"}, {"id": "M204", "type": "dialogue", "q": "A: I'm afraid I won't be able to finish the report by Friday.\nB: ______\nA: Thanks. I'll make sure you have it first thing Monday morning.", "options": ["Then you'd better hand it in on Thursday.", "Congratulations! You did a great job.", "That's all right. Monday will be fine.", "I've already read your report twice."], "answer": 2, "explain": "A 表示週五前無法完成報告，B 回答「沒關係，週一也可以」，A 才會道謝並保證週一一早交出。(A) 那你最好週四交，與 A 的回應「週一交」矛盾；(B) 恭喜，你做得很好，報告尚未完成，不合理；(D) 我已經讀了你的報告兩次，報告還沒寫完，前後矛盾。故選 (C)。", "level": "B2", "topic": "workplace"}, {"id": "M205", "type": "dialogue", "q": "A: You look pale. What's wrong?\nB: ______\nA: You should see a doctor and get some rest.", "options": ["I've had a terrible headache since this morning.", "I just won first prize in the speech contest.", "I'm going to the movies with my friends.", "Nothing much. I feel great today."], "answer": 0, "explain": "A 說 B 臉色蒼白、問怎麼了，B 回答「我從早上就頭痛得很厲害」，A 才會建議看醫生並休息。(B) 剛贏得演講比賽冠軍，是好消息，不會被建議看醫生；(C) 要和朋友去看電影，與身體不適無關；(D) 沒什麼，我今天感覺很好，A 不會叫他去看醫生。故選 (A)。", "level": "B1", "topic": "health"}, {"id": "M206", "type": "dialogue", "q": "A: Good morning. May I see your passport and ticket, please?\nB: Here you are.\nA: ______\nB: Just this one suitcase. I'll carry the backpack on board.", "options": ["How long will you be staying there?", "Do you have any bags to check in?", "Would you like chicken or fish for dinner?", "Have you been to Japan before?"], "answer": 1, "explain": "這是機場報到櫃台的對話。B 回答「只有這個行李箱，背包我會帶上飛機」，可知 A 問的是「有要托運的行李嗎？」check in 托運（行李）。(A) 你會停留多久，應回答時間長短；(C) 晚餐要雞肉還是魚，是機上空服員的問題；(D) 你去過日本嗎，應回答 Yes／No 與經驗。故選 (B)。", "level": "B2", "topic": "airport"}, {"id": "M207", "type": "dialogue", "q": "A: Can I borrow your notes from yesterday's history class?\nB: ______\nA: Thanks a lot. I'll give them back to you tomorrow.", "options": ["No, I've never taken history.", "I'd rather not go to the library.", "Sorry, I was absent yesterday, too.", "Sure. Here you go."], "answer": 3, "explain": "A 想借昨天歷史課的筆記，B 回答「當然，拿去吧」，A 才會道謝並說明天歸還。(A) 我從沒修過歷史，與「昨天的歷史課」矛盾；(B) 我寧可不去圖書館，答非所問；(C) 抱歉，我昨天也缺席，表示沒有筆記可借，A 不會道謝並說要歸還。故選 (D)。", "level": "B1", "topic": "school"}, {"id": "M208", "type": "dialogue", "q": "A: Would you like to go hiking this Saturday?\nB: ______\nA: No problem. How about Sunday, then?", "options": ["Sure. What time shall we meet?", "Yes, I love hiking in the mountains.", "I'd love to, but I have to work that day.", "It took us three hours to get there."], "answer": 2, "explain": "A 邀 B 週六去健行，B 婉拒「我很想去，但那天要上班」，A 才會說「沒關係，那改週日如何？」。I'd love to, but... 是委婉拒絕邀約的常用說法。(A)、(B) 都是答應邀約，A 不需要改期；(D) 我們花了三小時才到那裡，是談過去的事，答非所問。故選 (C)。", "level": "B2", "topic": "making plans"}, {"id": "M209", "type": "dialogue", "q": "A: How much is this backpack?\nB: ______\nA: That's a little expensive. Do you have anything cheaper?", "options": ["It's made of leather.", "It's 2,500 dollars.", "It comes in black and blue.", "You can pay at the counter."], "answer": 1, "explain": "A 問背包多少錢，B 回答「2,500 元」，A 才會說「有點貴，有沒有便宜一點的？」。(A) 是皮革做的，回答材質；(C) 有黑色和藍色，回答顏色；(D) 可以到櫃台結帳，回答付款地點，皆未回答價錢。故選 (B)。", "level": "B1", "topic": "shopping"}, {"id": "M210", "type": "dialogue", "q": "A: Front desk. How may I help you?\nB: ______\nA: I'm sorry about that. I'll send someone up to fix it right away.", "options": ["The air conditioner in my room isn't working.", "I'd like to book a table for two at seven.", "Could you tell me where the nearest bank is?", "I'd like to check out, please."], "answer": 0, "explain": "飯店櫃台問需要什麼協助，房客說「我房間的冷氣壞了」，櫃台才會道歉並說「馬上派人上去修理」。(B) 想訂七點兩人的位子，是餐廳訂位；(C) 詢問最近的銀行在哪；(D) 要辦理退房，三者都不需要派人修理東西。故選 (A)。", "level": "B2", "topic": "hotel"}, {"id": "M211", "type": "dialogue", "q": "A: Excuse me. Could we have the check, please?\nB: ______\nA: Thank you. Can I pay by credit card?", "options": ["Sorry, we don't have any tables available.", "Would you like something to drink first?", "Certainly. Here you are.", "The soup of the day is tomato."], "answer": 2, "explain": "客人要求結帳（check 帳單），服務生回答「當然，這是您的帳單」，客人接著問能否刷卡。(A) 抱歉沒有空位，是客人剛進門時的對話；(B) 要不要先喝點什麼，是點餐時的問題；(D) 今日例湯是番茄湯，與結帳無關。故選 (C)。", "level": "B1", "topic": "restaurant"}, {"id": "M212", "type": "dialogue", "q": "A: Do you think we could move the meeting to Thursday afternoon?\nB: ______\nA: Then let's make it Friday morning instead.", "options": ["Sure. Thursday afternoon works for me.", "The meeting lasted about two hours.", "I'll take notes during the meeting.", "I'm afraid I'll be visiting a client then."], "answer": 3, "explain": "A 提議把會議改到週四下午，B 回答「恐怕我那時要去拜訪客戶」，所以 A 才改提「那就改週五早上吧」。(A) 週四下午我可以，A 不需要再改時間；(B) 會議開了約兩小時，是談過去的會議；(C) 我會在會議中做筆記，未回應時間安排。故選 (D)。", "level": "B2", "topic": "workplace"}, {"id": "M213", "type": "dialogue", "q": "A: Excuse me. How can I get to the train station?\nB: ______\nA: Thank you very much.", "options": ["Go straight for two blocks and turn left. You can't miss it.", "The train leaves at 3:15.", "I usually take the train to work.", "No, I don't know when it opens."], "answer": 0, "explain": "A 問路「要怎麼去火車站？」，B 指路「直走兩個街區再左轉，你一定看得到」，A 道謝。You can't miss it. 表示「很好找」。(B) 火車三點十五分開，回答時間；(C) 我通常搭火車上班，答非所問；(D) 我不知道幾點開門，A 問的不是開放時間。故選 (A)。", "level": "B1", "topic": "directions"}, {"id": "M214", "type": "dialogue", "q": "A: I'm really sorry, but I spilled coffee on the book you lent me.\nB: ______\nA: That's very kind of you. I'll buy you a new one anyway.", "options": ["You should have been more careful. I want it back now.", "Don't worry about it. It's just an old book.", "I'd love a cup of coffee, thanks.", "I haven't finished reading it either."], "answer": 1, "explain": "A 道歉把咖啡灑在借來的書上，B 寬容地說「別擔心，只是一本舊書」，A 才會說「你人真好，我還是會買本新的給你」。(A) 你應該更小心，我現在就要拿回來，語氣是責備，A 不會說 That's very kind of you；(C) 我想喝杯咖啡，答非所問；(D) 我也還沒讀完，與道歉無關。故選 (B)。", "level": "B2", "topic": "apologizing"}, {"id": "M215", "type": "dialogue", "q": "A: Hello. Is this Lucky Pizza?\nB: ______\nA: Oh, I'm sorry. I must have dialed the wrong number.", "options": ["Yes. What would you like to order?", "Hold on. I'll get him for you.", "No, I'm afraid this is a private home.", "Sure. We deliver in 30 minutes."], "answer": 2, "explain": "A 問「這是幸運披薩嗎？」，B 回答「不是，這裡是住家」，A 才會道歉說「我一定是撥錯號碼了」。(A)、(D) 表示確實是披薩店，A 不會說打錯；(B) 稍等，我去叫他來，與詢問店名不符，A 也不會說撥錯號碼。故選 (C)。", "level": "B1", "topic": "phone call"}, {"id": "M216", "type": "dialogue", "q": "A: I'd like something for a sore throat.\nB: ______\nA: No, I don't. I'm not allergic to anything.", "options": ["Take one tablet after each meal.", "How long have you had a sore throat?", "You can find it in aisle five.", "Do you have any allergies to medicine?"], "answer": 3, "explain": "在藥局，A 想買治喉嚨痛的藥，藥師問「你對藥物有過敏嗎？」，A 回答「沒有，我對任何東西都不過敏」。(A) 每餐飯後吃一顆，是用藥指示，A 不會回答 No, I don't；(B) 喉嚨痛多久了，應回答一段時間；(C) 在第五排走道，與過敏無關。故選 (D)。", "level": "B2", "topic": "pharmacy"}, {"id": "M217", "type": "dialogue", "q": "A: Have you finished your science project yet?\nB: ______\nA: Me neither. Let's work on it together after school.", "options": ["Yes, I handed it in yesterday.", "Not yet. I still need to make the poster.", "Science is my favorite subject.", "I'll go to the science museum tomorrow."], "answer": 1, "explain": "A 問科學專題做完沒，B 回答「還沒，我還要做海報」，A 說「我也還沒（Me neither），放學後一起做吧」。Me neither 用來附和否定句。(A) 已經交了，與 Me neither 不符；(C) 自然是我最喜歡的科目，答非所問；(D) 明天要去科學博物館，未回答是否完成。故選 (B)。", "level": "B1", "topic": "school"}, {"id": "M218", "type": "dialogue", "q": "A: We're having a barbecue at our place on Sunday. Can you come?\nB: ______\nA: Great! See you then. Just bring yourself.", "options": ["I'd be glad to. Should I bring anything?", "Sorry, I've already made other plans.", "I had a barbecue with my family last week.", "That's very kind of you, but I'm busy that day."], "answer": 0, "explain": "A 邀請 B 週日來家裡烤肉，B 回答「我很樂意，需要帶什麼嗎？」，A 說「太好了，到時見，人來就好（Just bring yourself）」。(B)、(D) 都是婉拒邀請，A 不會說 Great! See you then；(C) 上週和家人烤過肉了，未回應邀約。故選 (A)。", "level": "B2", "topic": "invitation"}, {"id": "M219", "type": "dialogue", "q": "A: That'll be 380 dollars altogether.\nB: ______\nA: Sorry, we only take cash.", "options": ["Here's 400. Keep the change.", "Could you wrap it as a gift?", "Do you have it in red?", "Can I pay with my credit card?"], "answer": 3, "explain": "店員說總共 380 元，顧客問「可以刷信用卡嗎？」，店員回答「抱歉，我們只收現金」。(A) 這是 400 元，不用找了，已用現金付款，店員不會說只收現金；(B) 可以包裝成禮物嗎；(C) 有紅色的嗎，兩者都與付款方式無關。故選 (D)。", "level": "B1", "topic": "shopping"}, {"id": "M220", "type": "dialogue", "q": "A: I'd like to book a double room for this weekend.\nB: ______\nA: Two nights, Friday and Saturday.", "options": ["Would you like a window seat or an aisle seat?", "Breakfast is served from seven to ten.", "How many nights will you be staying?", "Your room is on the fifth floor."], "answer": 2, "explain": "A 要訂本週末的雙人房，櫃台問「您要住幾晚？」，A 回答「兩晚，週五和週六」。(A) 靠窗或靠走道座位，是訂機票或車票的問題；(B) 早餐供應時間是七點到十點；(D) 你的房間在五樓，是入住時的說明，皆無法接 Two nights。故選 (C)。", "level": "B2", "topic": "hotel"}, {"id": "M221", "type": "dialogue", "q": "A: Is that for here or to go?\nB: ______\nA: OK. Your order will be ready in five minutes.", "options": ["To go, please.", "I'll have a large coffee.", "It's too spicy for me.", "Yes, it's delicious."], "answer": 0, "explain": "店員問「內用還是外帶？」（for here or to go），顧客回答「外帶，謝謝」。(B) 我要一杯大杯咖啡，是點餐內容，沒有回答內用或外帶；(C) 對我來說太辣了；(D) 是的，很好吃，兩者都是吃過後的評價，不合情境。故選 (A)。", "level": "B1", "topic": "fast food"}, {"id": "M222", "type": "dialogue", "q": "A: The printer is jammed again. Do you know how to fix it?\nB: ______\nA: Never mind. I'll ask someone from the IT department.", "options": ["Sure. Just open this door and pull out the paper.", "I printed fifty copies this morning.", "Sorry, I have no idea how it works.", "Yes, it's a brand-new printer."], "answer": 2, "explain": "A 說印表機又卡紙了，問 B 會不會修，B 回答「抱歉，我完全不知道它怎麼運作」，A 才說「沒關係，我去問資訊部門的人」。jammed 卡住的。(A) 教 A 如何排除卡紙，A 不需再找資訊部門；(B) 我今早印了五十份，答非所問；(D) 是的，它是全新的印表機，未回答會不會修。故選 (C)。", "level": "B2", "topic": "workplace"}, {"id": "M223", "type": "dialogue", "q": "A: It looks like it's going to rain.\nB: ______\nA: Good idea. I'll grab mine, too.", "options": ["Let's go swimming at the beach.", "We'd better take our umbrellas.", "The weather was nice yesterday.", "I like rainy days the most."], "answer": 1, "explain": "A 說看起來快下雨了，B 建議「我們最好帶傘」，A 回答「好主意，我也去拿我的（傘）」，mine 指 my umbrella。(A) 去海邊游泳，與要下雨不合；(C) 昨天天氣很好，不是建議；(D) 我最喜歡雨天，不是建議，也無法對應 mine。故選 (B)。", "level": "B1", "topic": "weather"}, {"id": "M224", "type": "dialogue", "q": "A: Excuse me. Would you mind turning down the music? I'm trying to study.\nB: ______\nA: Thanks. I appreciate it.", "options": ["Yes, I'd love to listen to music.", "Sure. I'll turn it up for you.", "What kind of music do you like?", "Oh, sorry. I didn't realize it was so loud."], "answer": 3, "explain": "A 禮貌地請 B 把音樂關小聲（turn down），B 道歉說「抱歉，我沒發現這麼大聲」，表示會配合，A 才道謝。(A) 我很樂意聽音樂，答非所問；(B) turn up 是「調大聲」，與 A 的請求相反；(C) 你喜歡哪種音樂，未回應請求。故選 (D)。", "level": "B2", "topic": "polite request"}, {"id": "M225", "type": "dialogue", "q": "A: How did you do on the math test?\nB: ______\nA: Congratulations! All your hard work paid off.", "options": ["I got 95. I can't believe it!", "I failed it again.", "The test is next Monday.", "I didn't study at all."], "answer": 0, "explain": "A 問數學考得如何，B 回答「我考了 95 分，真不敢相信」，A 才會恭喜並說「你的努力有了回報（paid off）」。(B) 我又不及格了，A 不會說恭喜；(C) 考試在下週一，表示還沒考；(D) 我完全沒讀書，與「努力有回報」矛盾。故選 (A)。", "level": "B1", "topic": "school"}, {"id": "M226", "type": "dialogue", "q": "A: Good afternoon, Sunrise Travel. How can I help you?\nB: I'd like to change the date of my tour to Hualien.\nA: ______\nB: It's HT0825. I booked the tour last week.", "options": ["Hualien is famous for its beautiful scenery.", "What date would you like to change it to?", "Certainly. May I have your booking number, please?", "The tour bus leaves at eight in the morning."], "answer": 2, "explain": "B 打電話到旅行社想更改花蓮行程的日期，A 回答「當然，可以請您提供訂位編號嗎？」，B 才會報出編號 HT0825 並說明上週訂的。booking number 訂位編號。(A) 花蓮以美麗的風景聞名，答非所問；(B) 您想改到哪一天，B 應回答日期，而不是編號；(D) 遊覽車早上八點出發，未回應更改日期的需求，B 也不會接著報出編號。故選 (C)。", "level": "B2", "topic": "phone call"}, {"id": "M227", "type": "dialogue", "q": "A: I've gained five kilograms this year.\nB: ______\nA: You're right. I'll start jogging tomorrow.", "options": ["You should eat more snacks.", "Maybe you should exercise more.", "Congratulations on your new job.", "I've never been to the gym."], "answer": 1, "explain": "A 說今年胖了五公斤，B 建議「也許你該多運動」，A 回答「你說得對，我明天開始慢跑」。(A) 你應該多吃零食，與減重相反；(C) 恭喜你找到新工作，答非所問；(D) 我從沒去過健身房，不是建議，A 不會說 You're right。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M228", "type": "dialogue", "q": "A: I'd like to return this jacket. The zipper is broken.\nB: ______\nA: Yes, here it is. I bought it last Tuesday.", "options": ["Would you like to try a larger size?", "This jacket is on sale today.", "We close at nine on weekdays.", "Do you have the receipt with you?"], "answer": 3, "explain": "A 因拉鍊壞了要退外套，店員問「您有帶收據嗎？」，A 回答「有，在這裡，我上週二買的」。receipt 收據。(A) 要不要試大一號，與拉鍊壞掉無關；(B) 這件外套今天特價；(C) 我們平日九點打烊，三者都接不上 Yes, here it is。故選 (D)。", "level": "B2", "topic": "shopping"}, {"id": "M229", "type": "dialogue", "q": "A: Let's meet in front of the theater at 6:30.\nB: ______\nA: OK. Then let's make it seven.", "options": ["Could we make it a little later? I finish work at 6:30.", "Great. See you at 6:30.", "The movie was really boring.", "I don't like going to the theater alone."], "answer": 0, "explain": "A 約六點半在戲院前碰面，B 說「能晚一點嗎？我六點半才下班」，A 才改說「好，那就七點吧」。make it 在此指「約定（時間）」。(B) 好，六點半見，A 不需改時間；(C) 那部電影很無聊，是看完後的評論；(D) 我不喜歡一個人去戲院，與約時間無關。故選 (A)。", "level": "B1", "topic": "making plans"}, {"id": "M230", "type": "dialogue", "q": "A: Excuse me, waiter. This steak is overcooked. I asked for medium rare.\nB: ______\nA: Thank you. I'd appreciate that.", "options": ["Medium rare is our most popular choice.", "I'm terribly sorry. I'll have the chef cook you another one.", "Would you like some dessert after that?", "Our steaks come from Australia."], "answer": 1, "explain": "A 抱怨牛排煎過熟，他點的是三分熟（medium rare），服務生道歉並說「我請主廚再幫您煎一份」，A 才會說「謝謝，那就麻煩了」。(A) 三分熟是最受歡迎的選擇，未處理客訴；(C) 之後要甜點嗎，忽略抱怨；(D) 我們的牛排來自澳洲，答非所問。故選 (B)。", "level": "B2", "topic": "restaurant"}, {"id": "M231", "type": "dialogue", "q": "A: One ticket to Kaohsiung, please.\nB: ______\nA: One-way, please. I'm not coming back until next month.", "options": ["The train is leaving from Platform 3.", "It takes about two hours.", "Would you like a window seat?", "One-way or round-trip?"], "answer": 3, "explain": "A 要買一張到高雄的票，售票員問「單程還是來回？」，A 回答「單程，我下個月才回來」。(A) 火車從第三月台出發；(B) 車程大約兩小時；(C) 要靠窗座位嗎，三者都無法接 One-way, please。故選 (D)。", "level": "B1", "topic": "travel"}, {"id": "M232", "type": "dialogue", "q": "A: Why do you want to work for our company?\nB: ______\nA: I see. Your experience in design will be very useful here.", "options": ["I'd like to know how much I will be paid first.", "I'm not sure. My parents told me to apply.", "I've always admired your products, and I think my design skills would fit your team.", "I can start working next Monday."], "answer": 2, "explain": "面試官問為什麼想來公司工作，應徵者回答「我一直很欣賞貴公司的產品，也認為我的設計能力適合貴團隊」，面試官才會說「你的設計經驗在這裡會很有用」。(A) 我想先知道薪水多少，沒回答問題且不得體；(B) 不確定，是父母叫我應徵的，沒有提到設計；(D) 我下週一可以上班，回答的是到職日。故選 (C)。", "level": "B2", "topic": "job interview"}, {"id": "M233", "type": "dialogue", "q": "A: Excuse me. Is this seat taken?\nB: ______\nA: Thanks. I'll sit here, then.", "options": ["No, go ahead.", "Yes, my friend is sitting here.", "Sorry, I don't have the time.", "It's very comfortable."], "answer": 0, "explain": "A 問「這個位子有人坐嗎？」（Is this seat taken?），B 回答「沒有，請坐」，A 才會道謝並坐下。(B) 有，我朋友坐這裡，A 就不能坐；(C) 抱歉，我不知道現在幾點（I don't have the time），答非所問；(D) 它很舒服，沒有回答是否有人坐。故選 (A)。", "level": "B1", "topic": "polite request"}, {"id": "M234", "type": "dialogue", "q": "A: How long have you been coughing like this?\nB: ______\nA: I see. Let me listen to your chest.", "options": ["Three times a day, after meals.", "For about a week now.", "I'll take the medicine right away.", "I'll be fine in a few days."], "answer": 1, "explain": "醫生問「你像這樣咳嗽多久了？」（How long 問持續時間），病人回答「到現在大約一週了」，醫生接著要聽診胸部。(A) 一天三次、飯後，是回答頻率或服藥方式；(C) 我馬上吃藥，答非所問；(D) 我過幾天就會好，是推測未來，不是持續時間。故選 (B)。", "level": "B2", "topic": "health"}, {"id": "M235", "type": "dialogue", "q": "A: How many books can I borrow at a time?\nB: ______\nA: And how long can I keep them?", "options": ["The library opens at eight.", "You can't eat in the library.", "Up to five books.", "For two weeks."], "answer": 2, "explain": "A 問一次可以借幾本書，館員回答「最多五本」，A 再問可以借多久。(A) 圖書館八點開門，回答時間；(B) 圖書館內不能吃東西，答非所問；(D) 兩週，是回答「可以借多久」，應在 A 的下一個問題之後才出現。故選 (C)。", "level": "B1", "topic": "library"}, {"id": "M236", "type": "dialogue", "q": "A: I'm bored. What should we do this afternoon?\nB: ______\nA: Sounds good. I've wanted to see that exhibition for a while.", "options": ["Why don't we go to the art museum?", "Let's stay home and watch TV.", "I went to the museum last week.", "I'm too tired to go out."], "answer": 0, "explain": "A 說很無聊、問下午要做什麼，B 提議「我們何不去美術館？」，A 回答「好主意，我想看那個展覽很久了」。Why don't we...? 用來提出建議。(B) 待在家看電視，與「展覽」無關；(C) 我上週去過博物館，不是提議；(D) 我太累了不想出門，A 不會說 Sounds good。故選 (A)。", "level": "B1", "topic": "making plans"}, {"id": "M237", "type": "dialogue", "q": "A: Can I help you?\nB: ______\nA: All right. Let me know if you need anything.", "options": ["Yes, I'm looking for a pair of running shoes.", "Yes, please. How much is this?", "No, I can't help you.", "No, thanks. I'm just looking."], "answer": 3, "explain": "店員問「需要幫忙嗎？」，顧客回答「不用了，謝謝，我只是看看」，店員說「好的，需要什麼再告訴我」。(A)、(B) 都是提出需求，店員應會直接協助或報價，而不是說有需要再叫我；(C) 我不能幫你，誤解了店員的問題。故選 (D)。", "level": "B1", "topic": "shopping"}, {"id": "M238", "type": "dialogue", "q": "A: I heard Jenny is in the hospital.\nB: ______\nA: Me too. Let's visit her after work.", "options": ["Yes, she just got a promotion.", "Really? I hope she gets well soon.", "I'm glad to hear that.", "Yes, she's on vacation in Japan."], "answer": 1, "explain": "A 說聽說 Jenny 住院了，B 回答「真的嗎？希望她早日康復」，A 說「我也是（希望），下班後去探望她吧」。(A) 她剛升職，與住院無關；(C) 我很高興聽到這消息，對住院的壞消息不恰當；(D) 她在日本度假，與住院矛盾。故選 (B)。", "level": "B2", "topic": "workplace"}, {"id": "M239", "type": "dialogue", "q": "A: Good evening. Ocean Restaurant.\nB: ______\nA: Of course. For what time?", "options": ["Can I have the check, please?", "The food here is excellent.", "I'd like to reserve a table for four tomorrow night.", "I've been waiting for half an hour."], "answer": 2, "explain": "這是打電話到餐廳的對話，B 說「我想訂明晚四人的位子」，A 回答「當然，請問幾點？」。reserve a table 訂位。(A) 請給我帳單，是在店內用餐後說的；(B) 這裡的食物很棒，是評價；(D) 我已經等了半小時，是抱怨，三者都接不上 For what time?。故選 (C)。", "level": "B1", "topic": "restaurant"}, {"id": "M240", "type": "dialogue", "q": "A: Excuse me. I think I'm lost. Where are we on this map?\nB: ______\nA: Oh, I see. So the museum is just around the corner.", "options": ["We're right here, near the post office.", "You can buy a map at the bookstore.", "Sorry, I'm a stranger here myself.", "It's a beautiful city, isn't it?"], "answer": 0, "explain": "A 迷路了，問我們在地圖上的哪裡，B 指著地圖說「我們就在這裡，郵局附近」，A 才明白「所以博物館就在轉角」。(B) 可以在書店買地圖，A 已經有地圖；(C) 抱歉，我也不是本地人，A 不會說 Oh, I see；(D) 這城市很美，對吧，答非所問。故選 (A)。", "level": "B2", "topic": "travel"}, {"id": "M241", "type": "dialogue", "q": "A: Hello? Can you hear me?\nB: ______\nA: Sorry, I'm on the train. I'll call you back later.", "options": ["Yes, loud and clear.", "Thanks for calling.", "I'll be home at eight.", "You're breaking up. I can hardly hear you."], "answer": 3, "explain": "A 問「聽得到我說話嗎？」，B 回答「你的聲音斷斷續續，我幾乎聽不到」，A 才解釋自己在火車上、晚點再回電。breaking up 指通話訊號不穩、斷斷續續。(A) 聽得很清楚，A 不需要晚點再打；(B) 謝謝來電，通常用於結束通話；(C) 我八點會到家，答非所問。故選 (D)。", "level": "B2", "topic": "phone call"}, {"id": "M242", "type": "dialogue", "q": "A: Who's going to give the presentation for our group?\nB: ______\nA: Good. You're the best speaker among us.", "options": ["I don't think we need a presentation.", "I'll do it if nobody else wants to.", "The presentation was last Friday.", "I'm too nervous to speak in public."], "answer": 1, "explain": "A 問誰要代表小組上台報告，B 說「如果沒人想做，我來吧」，A 回答「很好，你是我們之中最會說話的人」。(A) 我覺得不需要報告，A 不會說 Good；(C) 報告是上週五，表示已經結束；(D) 我太緊張不敢公開演講，與 A 稱讚他是最佳講者矛盾。故選 (B)。", "level": "B1", "topic": "school"}, {"id": "M243", "type": "dialogue", "q": "A: These apples look fresh. How much are they?\nB: ______\nA: I'll take six, then.", "options": ["They come from Lishan.", "We've sold out of apples.", "Three for 100 dollars.", "They're not ripe yet."], "answer": 2, "explain": "A 問蘋果多少錢，老闆回答「三顆一百元」，A 說「那我買六顆」。(A) 產自梨山，回答產地不是價錢；(B) 蘋果賣完了，A 就買不到；(D) 還沒熟，沒回答價錢，A 也不會接著買。故選 (C)。", "level": "B1", "topic": "shopping"}, {"id": "M244", "type": "dialogue", "q": "A: Your bags look heavy. Would you like me to help you with them?\nB: ______\nA: No problem. Where should I put them?", "options": ["That's very kind of you. Thanks.", "No, thanks. I can manage.", "I bought them at the department store.", "Yes, they're very light."], "answer": 0, "explain": "A 主動表示要幫忙提重物，B 接受並道謝「你真好心，謝謝」，A 回答「不客氣，要放在哪裡？」。(B) 不用了，我自己可以，A 就不會問放哪裡；(C) 我在百貨公司買的，答非所問；(D) 是的，它們很輕，與 A 說袋子看起來很重矛盾，也沒有接受幫忙。故選 (A)。", "level": "B2", "topic": "offering help"}, {"id": "M245", "type": "dialogue", "q": "A: What happened to your leg?\nB: ______\nA: That's terrible. Does it still hurt?", "options": ["I bought new jeans yesterday.", "I hurt it while playing basketball.", "My legs are longer than yours.", "I'm going to the hospital to visit my aunt."], "answer": 1, "explain": "A 問 B 的腳怎麼了，B 回答「我打籃球時受傷了」，A 說「真糟糕，還會痛嗎？」。(A) 我昨天買了新牛仔褲；(C) 我的腿比你長；(D) 我要去醫院探望阿姨，三者都沒有說明腳受傷，A 不會問還痛不痛。故選 (B)。", "level": "B1", "topic": "health"}, {"id": "M246", "type": "dialogue", "q": "A: Could you lend me your laptop for the meeting this afternoon?\nB: ______\nA: That's OK. I'll ask Tom instead.", "options": ["Sure. Just bring it back by five.", "The meeting starts at two o'clock.", "I bought it two years ago.", "Sorry, I need it for my own presentation."], "answer": 3, "explain": "A 想借筆電開會，B 婉拒「抱歉，我自己的簡報要用」，A 才說「沒關係，我改問 Tom」。(A) 答應出借，A 不需改問別人；(B) 會議兩點開始，未回應借用請求；(C) 我兩年前買的，答非所問。故選 (D)。", "level": "B2", "topic": "workplace"}, {"id": "M247", "type": "dialogue", "q": "A: Tomorrow is Mom's birthday. What should we get her?\nB: ______\nA: Good idea. She spends hours in the garden every weekend.", "options": ["Her birthday was last month.", "She's 45 years old.", "How about a set of gardening tools?", "I've already eaten the cake."], "answer": 2, "explain": "A 問明天媽媽生日要送什麼，B 提議「送一套園藝工具如何？」，A 回答「好主意，她每個週末都在花園待好幾個小時」。How about...? 用來提出建議。(A) 她的生日是上個月，與 A 說「明天生日」矛盾；(B) 她 45 歲，沒有提出建議；(D) 我已經把蛋糕吃了，答非所問。故選 (C)。", "level": "B1", "topic": "family"}, {"id": "M248", "type": "dialogue", "q": "A: What's the purpose of your visit?\nB: ______\nA: Thank you. Enjoy your stay.", "options": ["I'm here on vacation.", "I'll be staying for ten days.", "I came by plane.", "I have nothing to declare."], "answer": 0, "explain": "入境審查時，官員問「您來訪的目的是什麼？」（purpose 目的），旅客回答「我來度假」。(B) 我會停留十天，回答停留時間；(C) 我搭飛機來，回答交通方式；(D) 我沒有東西要申報，是海關申報的用語，三者皆未回答目的。故選 (A)。", "level": "B1", "topic": "immigration"}, {"id": "M249", "type": "dialogue", "q": "A: Why are you late for class again?\nB: ______\nA: Then you should get up earlier tomorrow.", "options": ["I always come to school by bike.", "I'm sorry. I overslept this morning.", "Because the class is very interesting.", "I'll finish my homework tonight."], "answer": 1, "explain": "老師問 B 為什麼又遲到，B 回答「對不起，我今天早上睡過頭了（overslept）」，老師才說「那你明天應該早點起床」。(A) 我總是騎腳踏車上學，未說明遲到原因；(C) 因為這堂課很有趣，不是遲到的理由；(D) 我今晚會寫完作業，答非所問。故選 (B)。", "level": "B1", "topic": "school"}, {"id": "M250", "type": "dialogue", "q": "A: Everything on the menu looks good. What do you recommend?\nB: ______\nA: Hmm, I'm not a big fan of spicy food. Is there anything milder?", "options": ["Here's your change.", "The restrooms are over there.", "Would you like your coffee now or later?", "Our spicy chicken is very popular."], "answer": 3, "explain": "客人請服務生推薦菜色，服務生說「我們的辣子雞很受歡迎」，客人才說「我不太愛吃辣，有沒有比較不辣的？」。milder 較溫和的、較不辣的。(A) 這是找您的零錢，是結帳時說的；(B) 洗手間在那邊，答非所問；(C) 咖啡要現在上還是待會上，沒有推薦菜色，也與辣無關。故選 (D)。", "level": "B2", "topic": "restaurant"}, {"id": "M251", "type": "dialogue", "q": "A: That'll be 285 dollars. Would you like a plastic bag?\nB: ______ I brought my own.\nA: Great. Thank you for helping the environment.", "options": ["Yes, two bags, please.", "Here's your receipt.", "No, thanks.", "Sorry, I only have cash."], "answer": 2, "explain": "店員告知金額並詢問是否需要塑膠袋；B 接著說「我自己有帶（袋子）」，店員也感謝 B 愛護環境，可知 B 婉拒了塑膠袋。(C)「不用了，謝謝」最恰當。(A)「好，請給我兩個袋子」與自備購物袋矛盾；(B)「這是你的收據」應是店員說的話；(D)「抱歉，我只有現金」與要不要袋子無關。故選 (C)。", "level": "B1", "topic": "shopping"}, {"id": "M252", "type": "dialogue", "q": "A: Excuse me. Do you have Wi-Fi here?\nB: ______ The password is printed on your receipt.", "options": ["Yes, it's free for customers.", "No, we don't take credit cards.", "Sorry, we're out of milk.", "It's on the second floor."], "answer": 0, "explain": "顧客問店裡有沒有 Wi-Fi；店員接著說「密碼印在你的收據上」，可知店裡有提供 Wi-Fi。(A)「有，顧客可以免費使用」最合理。(B)「不，我們不收信用卡」答非所問；(C)「抱歉，牛奶賣完了」與 Wi-Fi 無關；(D)「在二樓」回答的是位置，與提供密碼不連貫。故選 (A)。", "level": "B1", "topic": "cafe"}, {"id": "M253", "type": "dialogue", "q": "A: Where to, miss?\nB: ______\nA: OK. It'll take about twenty minutes if the traffic is light.", "options": ["Keep the change.", "It's 300 dollars.", "I'm from Kaohsiung.", "Taipei Main Station, please."], "answer": 3, "explain": "「Where to?」是計程車司機問乘客「要去哪裡？」的常用說法，應回答目的地；司機接著說路況順暢的話約需二十分鐘。(D)「請到臺北車站」最恰當。(A)「不用找了」是下車付款時說的話；(B)「要 300 元」是司機告知車資的話；(C)「我來自高雄」回答的是出身地，不是目的地。故選 (D)。", "level": "B1", "topic": "taxi"}, {"id": "M254", "type": "dialogue", "q": "A: I'd like to send this package to Japan.\nB: ______\nA: By airmail, please. I want it to get there quickly.", "options": ["What's inside the box?", "How would you like to send it?", "Where is the post office?", "When did you receive it?"], "answer": 1, "explain": "A 在郵局要把包裹寄到日本；A 接著回答「寄航空，我希望快點寄到」，可知郵局人員問的是寄送方式。(B)「您想用什麼方式寄？」最合理。(A)「箱子裡裝什麼？」應回答物品內容；(C)「郵局在哪裡？」A 已經在郵局，答句也不符；(D)「你什麼時候收到的？」與寄件無關。故選 (B)。", "level": "B1", "topic": "post office"}, {"id": "M255", "type": "dialogue", "q": "A: Guess what? I passed my driving test!\nB: ______ You must be so happy.", "options": ["Congratulations!", "Better luck next time.", "Take care.", "That's too bad."], "answer": 0, "explain": "A 興奮地說自己通過了駕照考試；B 接著說「你一定很開心」，可知 B 在祝賀對方。(A)「恭喜！」最恰當。(B)「下次運氣會更好」用於安慰失敗的人；(C)「保重」是道別或叮嚀用語；(D)「那真糟糕」用於回應壞消息，皆不符合語境。故選 (A)。", "level": "B1", "topic": "good news"}, {"id": "M256", "type": "dialogue", "q": "A: Could you make thirty copies of this handout before the meeting?\nB: ______\nA: Yes, please. Staple them in the top left corner.", "options": ["The copy machine is on the third floor.", "I've already read it twice.", "Sure. Would you like them stapled?", "No, thanks. I don't need a copy."], "answer": 2, "explain": "A 請 B 在開會前把講義印三十份；A 接著說「好，麻煩釘在左上角」，可知 B 問了要不要裝訂。(C)「沒問題，要幫你釘起來嗎？」最合理，staple 意為「用釘書機釘」。(A)「影印機在三樓」無法用 Yes, please 回應；(B)「我已經讀過兩次了」答非所問；(D)「不用了，我不需要一份」誤以為對方要給自己講義，與請託不符。故選 (C)。", "level": "B2", "topic": "office tasks"}, {"id": "M257", "type": "dialogue", "q": "A: You look sad. What's wrong?\nB: My dog, Lucky, died last week. He was fourteen.\nA: ______ He was such a sweet dog.", "options": ["Good for you.", "I'm so sorry to hear that.", "Congratulations!", "No wonder you look happy."], "answer": 1, "explain": "B 說家裡的狗 Lucky 上週過世了；A 接著說「牠是隻很貼心的狗」，可知 A 在表達同情與安慰。(B)「聽到這件事我很難過」最恰當。(A)「真替你高興」、(C)「恭喜！」都用於回應好消息；(D)「難怪你看起來很開心」與 B 看起來很難過矛盾。故選 (B)。", "level": "B1", "topic": "sympathy"}, {"id": "M258", "type": "dialogue", "q": "A: Reception. What can I do for you?\nB: ______\nA: Certainly. We'll call your room at six.", "options": ["I'd like to check out now.", "Could you send someone to fix the TV?", "What time is breakfast served?", "Could I have a wake-up call at six tomorrow morning?"], "answer": 3, "explain": "B 打電話到飯店櫃檯；櫃檯人員回答「沒問題，我們六點會打電話到您房間」，可知 B 要求晨喚服務。(D)「明天早上六點可以打電話叫我起床嗎？」（wake-up call 晨喚電話）最合理。(A)「我現在要退房」不需要隔天早上打電話；(B)「可以派人來修電視嗎？」櫃檯應回答會派人上樓；(C)「早餐幾點供應？」應回答供餐時間，而不是打電話到房間。故選 (D)。", "level": "B2", "topic": "hotel"}, {"id": "M259", "type": "dialogue", "q": "A: Oops! Sorry, I didn't see you there.\nB: ______ It was my fault, too. I was looking at my phone.", "options": ["That's all right.", "You're welcome.", "Yes, you did.", "Nice to see you."], "answer": 0, "explain": "A 撞到 B 後道歉；B 接著說「我也有錯，我剛剛在看手機」，可知 B 並不介意。(A)「沒關係」最恰當。(B)「不客氣」用於回應道謝；(C)「對，你明明看到了」與 A 說的話不合，也與 B 承認自己有錯矛盾；(D)「很高興見到你」是寒暄用語，不適合回應道歉。故選 (A)。", "level": "B1", "topic": "apology"}, {"id": "M260", "type": "dialogue", "q": "A: Do you have a table for three?\nB: I'm afraid we're full right now. ______\nA: That's fine. We'll wait. Could you put our name on the list?", "options": ["Please come back tomorrow.", "Would you like to order now?", "There should be a table in about fifteen minutes.", "Enjoy your meal."], "answer": 2, "explain": "A 想要三人桌，但餐廳目前客滿；A 接著說「沒關係，我們等，請幫我們登記候位」，可知 B 告知了大約要等多久。(C)「大約十五分鐘後應該會有空位」最合理。(A)「請明天再來」表示今天沒辦法，A 不會說要等；(B)「現在要點餐嗎？」還沒入座無法點餐；(D)「請慢用」是上菜時的用語。故選 (C)。", "level": "B2", "topic": "restaurant"}, {"id": "M261", "type": "dialogue", "q": "A: Excuse me. Does this bus go to the zoo?\nB: ______ You need to take No. 5. The stop is across the street.", "options": ["Yes, it stops right in front of the zoo.", "Sure. Hop on.", "It costs 15 dollars.", "No, I'm afraid it doesn't."], "answer": 3, "explain": "A 問這班公車有沒有到動物園；B 接著說「你要搭 5 號，站牌在對街」，可知這班車不到動物園。(D)「不，恐怕沒有」最合理。(A)「有，它就停在動物園門口」、(B)「當然，上車吧」都表示這班車會到，與後文矛盾；(C)「車資 15 元」答非所問。故選 (D)。", "level": "B1", "topic": "public transport"}, {"id": "M262", "type": "dialogue", "q": "A: Can everyone see my screen?\nB: Yes, we can see it. ______\nA: Oh, sorry. I forgot to turn on my microphone. Can you hear me now?", "options": ["Your voice is too loud.", "But I'm afraid we can't hear you.", "Could you turn off your microphone?", "Your camera is broken."], "answer": 1, "explain": "線上課程中 A 問大家看不看得到螢幕；A 接著說「抱歉，我忘了開麥克風，現在聽得到嗎？」，可知 B 反映聽不到聲音。(B)「不過我們好像聽不到你的聲音」最合理。(A)「你的聲音太大了」與聽不到矛盾；(C)「你可以把麥克風關掉嗎？」與 A 原本沒開麥克風的情況相反；(D)「你的鏡頭壞了」與聲音無關，A 也不會接著問聽不聽得到。故選 (B)。", "level": "B2", "topic": "online class"}, {"id": "M263", "type": "dialogue", "q": "A: Do you offer a student discount?\nB: Yes, ten percent off. ______\nA: Sure. Here it is.", "options": ["Would you like to join our club?", "How old are you?", "May I see your student ID?", "Where do you study?"], "answer": 2, "explain": "A 問有沒有學生優惠；店員說打九折（ten percent off），A 接著說「好的，在這裡」並遞出東西，可知店員要求出示證件。(C)「可以看一下你的學生證嗎？」最合理。(A)「要加入我們的會員嗎？」不能用 Here it is 回答；(B)「你幾歲？」、(D)「你在哪裡讀書？」都應回答年齡或學校名稱。故選 (C)。", "level": "B1", "topic": "shopping"}, {"id": "M264", "type": "dialogue", "q": "A: I've been feeling really stressed out because of the upcoming exams.\nB: ______ Taking a walk or listening to music might help.", "options": ["Why don't you take a short break?", "You must be very proud of yourself.", "How about studying all night?", "I'm glad you're feeling better."], "answer": 0, "explain": "A 說因為即將到來的考試而壓力很大；B 接著建議「散散步或聽聽音樂可能有幫助」，可知 B 在勸對方放鬆一下。(A)「你何不稍微休息一下？」最恰當。(B)「你一定很以自己為傲」與壓力大的情境不符；(C)「要不要熬夜讀書？」會讓壓力更大，與後面放鬆的建議矛盾；(D)「真高興你好多了」與 A 現在仍覺得壓力大矛盾。故選 (A)。", "level": "B2", "topic": "stress"}, {"id": "M265", "type": "dialogue", "q": "A: Oh no, I can't find my wallet anywhere!\nB: ______\nA: At the convenience store. I bought a drink there after school.", "options": ["How much money was in it?", "Where did you last use it?", "What color is it?", "Why did you buy a drink?"], "answer": 1, "explain": "A 找不到錢包；A 接著回答「在便利商店，我放學後在那裡買了飲料」，可知 B 問的是最後一次使用錢包的地點。(B)「你最後一次是在哪裡用它？」最合理。(A)「裡面有多少錢？」應回答金額；(C)「是什麼顏色？」應回答顏色；(D)「你為什麼要買飲料？」應說明理由，皆與答句不符。故選 (B)。", "level": "B1", "topic": "lost item"}, {"id": "M266", "type": "dialogue", "q": "A: Welcome! Come on in. ______\nB: Thanks. What a lovely apartment!", "options": ["Who are you looking for?", "Sorry, I'm on my way out.", "Did you bring me a gift?", "Make yourself at home."], "answer": 3, "explain": "A 歡迎客人進門；B 道謝並稱讚房子很漂亮，可知 A 說了招呼客人的客套話。(D)「別拘束，就當自己家」最恰當。(A)「你要找誰？」與已邀請對方進門矛盾；(B)「抱歉，我正要出門」與歡迎客人不符；(C)「你有帶禮物給我嗎？」不禮貌，B 也不會以「謝謝」回應。故選 (D)。", "level": "B1", "topic": "visiting"}, {"id": "M267", "type": "dialogue", "q": "A: Your English presentation was excellent! You spoke so clearly.\nB: ______ I practiced it in front of the mirror many times.", "options": ["No, it's not my fault.", "Don't mention it.", "Thanks. I'm glad you liked it.", "I'm sorry to hear that."], "answer": 2, "explain": "A 稱讚 B 的英文報告很棒、說得很清楚；B 接著說自己對著鏡子練習了很多次，因此應先道謝、接受稱讚。(C)「謝謝，很高興你喜歡」最恰當。(A)「不，那不是我的錯」用於被指責時；(B)「不客氣」用於回應別人的道謝，而非稱讚；(D)「聽到這消息很遺憾」用於回應壞消息。故選 (C)。", "level": "B1", "topic": "compliments"}, {"id": "M268", "type": "dialogue", "q": "A: Let's go see the new superhero movie this weekend.\nB: Sounds good. ______\nA: How about Sunday afternoon? There's a show at three.", "options": ["When are you free?", "Who's the director?", "Where did you see it?", "How was the movie?"], "answer": 0, "explain": "A 提議週末去看電影，B 同意後問了一個問題；A 回答「週日下午如何？三點有一場」，可知 B 問的是時間。(A)「你什麼時候有空？」最合理。(B)「導演是誰？」無法用時間回答；(C)「你在哪裡看的？」、(D)「電影好看嗎？」都表示 A 已經看過，與「這週末要去看」矛盾。故選 (A)。", "level": "B1", "topic": "making plans"}, {"id": "M269", "type": "dialogue", "q": "A: Could you cover my shift at the cafe on Saturday? My cousin is getting married.\nB: ______ Just remember to tell the manager about the change.\nA: I will. Thanks so much!", "options": ["Congratulations on your wedding!", "Sorry, I'm working that day, too.", "Why didn't you invite me?", "No problem. I'm free that day."], "answer": 3, "explain": "cover one's shift 意為「代某人的班」。A 因表親要結婚，請 B 週六幫忙代班；B 接著提醒 A 記得告訴店長換班的事，A 也道謝，可知 B 答應了。(D)「沒問題，我那天有空」最恰當。(A)「恭喜你結婚」搞錯了結婚的人；(B)「抱歉，我那天也要上班」表示無法代班，與後文矛盾；(C)「你怎麼沒邀請我？」答非所問。故選 (D)。", "level": "B2", "topic": "part-time job"}, {"id": "M270", "type": "dialogue", "q": "A: Excuse me, but you're not allowed to eat in the library.\nB: ______ I'll finish my sandwich outside.", "options": ["Help yourself.", "Oh, I'm sorry. I didn't know that.", "That's very kind of you.", "Yes, it's delicious."], "answer": 1, "explain": "A 提醒 B 圖書館內不能吃東西；B 接著說要到外面把三明治吃完，可知 B 接受勸告並道歉。(B)「喔，抱歉，我不知道」最合理。(A)「請自便」用於招待他人；(C)「你真好心」用於回應別人的幫忙或好意，用來回應規勸並不自然；(D)「對啊，很好吃」答非所問。故選 (B)。", "level": "B1", "topic": "library rules"}, {"id": "M271", "type": "dialogue", "q": "A: How would you like your hair cut today?\nB: ______ I want to keep it long.\nA: Sure. I'll just take off about two centimeters.", "options": ["Just a trim, please.", "Very short, please.", "Every two months.", "It took about an hour."], "answer": 0, "explain": "美髮師問 B 今天想怎麼剪；B 接著說「我想留長」，美髮師也說只剪掉約兩公分，可知 B 只要稍微修一下。(A)「稍微修剪就好」（trim 修剪）最恰當。(B)「請剪很短」與想留長矛盾；(C)「每兩個月一次」回答頻率；(D)「花了大約一小時」回答所花時間，皆答非所問。故選 (A)。", "level": "B2", "topic": "hair salon"}, {"id": "M272", "type": "dialogue", "q": "A: Do you have a pen I could borrow? Mine just ran out of ink.\nB: ______ But I need it back after class.", "options": ["No, I don't have any ink.", "Sorry, I lent it to you.", "Sure. Here's a blue one.", "Thanks. I'll return it soon."], "answer": 2, "explain": "A 的筆沒水了，想跟 B 借筆；B 接著說「但下課後要還我」，可知 B 答應借出。(C)「當然，這枝藍色的給你」最合理。(A)「不，我沒有墨水」表示拒絕且答非所問；(B)「抱歉，我借給你了」語意矛盾；(D)「謝謝，我很快就還你」是借東西的人才會說的話。故選 (C)。", "level": "B1", "topic": "school"}, {"id": "M273", "type": "dialogue", "q": "A: I heard you joined the school band. ______\nB: The trumpet. I've been learning it since junior high.", "options": ["How often do you practice?", "What instrument do you play?", "When is your next concert?", "Who is your music teacher?"], "answer": 1, "explain": "A 聽說 B 參加了學校的管樂隊；B 回答「小喇叭，我從國中就開始學了」，可知 A 問的是樂器。(B)「你演奏什麼樂器？」最合理。(A)「你多久練習一次？」應回答頻率；(C)「下次表演是什麼時候？」應回答時間；(D)「你的音樂老師是誰？」應回答人名，皆無法用「小喇叭」回答。故選 (B)。", "level": "B1", "topic": "school club"}, {"id": "M274", "type": "dialogue", "q": "A: How do the shoes fit?\nB: ______ Do you have them in half a size bigger?", "options": ["They fit perfectly.", "They're a little loose.", "I'll take them.", "They're a bit tight around the toes."], "answer": 3, "explain": "店員問鞋子合不合腳；B 接著問有沒有大半號的，可知鞋子太小。(D)「腳趾的地方有點緊」最合理。(A)「非常合腳」就不需要換尺寸；(B)「有點鬆」應該換小一點的；(C)「我要買這雙」表示已決定購買，與要求換尺寸矛盾。故選 (D)。", "level": "B2", "topic": "shopping"}, {"id": "M275", "type": "dialogue", "q": "A: Excuse me. Would you mind switching seats with me? ______\nB: Not at all. Let me just grab my bag.", "options": ["I'd prefer to stand for the whole trip.", "This seat is too comfortable for me.", "I'd like to sit next to my daughter.", "You're sitting in the wrong car."], "answer": 2, "explain": "A 在車上請 B 和自己換座位，並在空格說明理由；B 回答「一點也不介意，我拿一下包包」，表示同意。(C)「我想坐在我女兒旁邊」是合理的換位理由。(A)「我寧願整趟路都站著」就不需要換座位；(B)「這個位子對我來說太舒服了」不合邏輯；(D)「你坐錯車廂了」應請對方離開，而不是和對方交換座位。故選 (C)。", "level": "B2", "topic": "travel"}, {"id": "M276", "type": "dialogue", "q": "A: Mr. Wang, would you mind if I left work an hour early today? My son is sick.\nB: ______ I hope he gets well soon.", "options": ["Not at all. Go ahead.", "Yes, I'd be glad to.", "Sure. I'll leave early, too.", "No, you can't stay here."], "answer": 0, "explain": "「Would you mind if I...?」字面意思是「你介意我……嗎？」，要表示同意須用否定回答。B 接著祝 A 的兒子早日康復，可知 B 准許 A 提早下班。(A)「一點也不介意，去吧」最恰當。(B)「是的，我很樂意」用 Yes 回答表示「介意」，且 I'd be glad to 是答應幫忙的說法；(C)「好，我也要提早走」答非所問；(D)「不，你不能待在這裡」語意不通。故選 (A)。", "level": "B2", "topic": "workplace"}, {"id": "M277", "type": "dialogue", "q": "A: Excuse me. Could you take a picture of us?\nB: ______ Just press this button, right?", "options": ["No, thanks. I don't need any.", "Say cheese!", "Here's my camera.", "Sure, no problem."], "answer": 3, "explain": "A 請 B 幫忙拍照；B 接著確認「按這個鍵就好，對吧？」，可知 B 答應幫忙。(D)「當然，沒問題」最恰當。(A)「不用了，謝謝，我不需要」用於拒絕別人提供的東西；(B)「笑一個！」是按快門前才說的，不會出現在確認操作方式之前；(C)「這是我的相機」應由請人拍照的 A 說，而不是 B。故選 (D)。", "level": "B1", "topic": "sightseeing"}, {"id": "M278", "type": "dialogue", "q": "A: We need more volunteers for the beach cleanup this Sunday. ______\nB: Count me in. What time should I be there?", "options": ["Have you ever been to the beach?", "Would you be interested in helping?", "Did you enjoy the cleanup?", "Why is the beach so dirty?"], "answer": 1, "explain": "A 說這週日的淨灘活動需要更多志工；B 回答「算我一份，我該幾點到？」，可知 A 在邀請 B 參加。(B)「你有興趣來幫忙嗎？」最合理。(A)「你去過海邊嗎？」應回答 Yes/No；(C)「你喜歡那次淨灘嗎？」表示活動已結束，與「這週日」矛盾；(D)「海灘為什麼這麼髒？」不能用 Count me in 回答。故選 (B)。", "level": "B2", "topic": "volunteering"}, {"id": "M279", "type": "dialogue", "q": "A: The meeting will be in Room 302 at 3:15. Please bring your ID card and the signed form.\nB: ______ I'm writing it down.\nA: Sure. Room 302, at 3:15.", "options": ["That's all I need, thanks.", "Can you write it down for me?", "Sorry, could you say that more slowly?", "I've already been there."], "answer": 2, "explain": "A 一口氣說出會議地點、時間和要帶的東西；B 說「我正在抄下來」，A 接著放慢速度重複「302 室，3 點 15 分」，可知 B 請 A 說慢一點。(C)「抱歉，可以說慢一點嗎？」最恰當。(A)「我只需要這些，謝謝」A 就不必再重複；(B)「你可以幫我寫下來嗎？」與 B 自己正在抄寫矛盾；(D)「我已經去過了」答非所問。故選 (C)。", "level": "B2", "topic": "asking to repeat"}, {"id": "M280", "type": "dialogue", "q": "A: Dinner is on me tonight. You helped me so much with my move.\nB: ______ Next time, it's my treat.", "options": ["Thanks. That's very generous of you.", "OK. Let's split the bill.", "No, I've already eaten.", "Sorry, I don't have time to help you."], "answer": 0, "explain": "「Dinner is on me.」意為「晚餐我請客」，A 為了感謝 B 幫忙搬家而請客；B 接著說「下次換我請」，可知 B 接受了好意。(A)「謝謝，你真大方」最恰當。(B)「好，我們各付各的」與 A 請客及「下次換我請」矛盾；(C)「不，我已經吃過了」表示拒絕，與下次換我請不連貫；(D)「抱歉，我沒空幫你」與情境無關，A 已經搬完家了。故選 (A)。", "level": "B2", "topic": "treating"}, {"id": "M281", "type": "dialogue", "q": "A: My computer just crashed, and I lost the file I was working on.\nB: ______ Next time, remember to save your work every few minutes.", "options": ["Congratulations!", "Oh, no. That's terrible.", "It's up to you.", "I couldn't agree more."], "answer": 1, "explain": "A 說電腦當機，正在處理的檔案不見了；B 接著提醒下次要每隔幾分鐘存檔，可知 B 先對這件倒楣事表示同情。(B)「喔，不，真糟糕」最恰當。(A)「恭喜！」用於好消息；(C)「由你決定」用於對方徵詢意見時；(D)「我完全同意」用於贊同別人的看法，皆不合語境。故選 (B)。", "level": "B1", "topic": "office"}, {"id": "M282", "type": "dialogue", "q": "A: Should we take the MRT or a taxi to the concert tonight?\nB: ______ The traffic will be terrible on a Friday night.", "options": ["Let's take a taxi. It's more comfortable.", "The concert starts at eight.", "I've never been to a concert.", "The MRT would be better."], "answer": 3, "explain": "A 問今晚去演唱會要搭捷運還是計程車；B 接著說「星期五晚上一定很塞」，可知 B 選擇不受塞車影響的捷運。(D)「搭捷運比較好」最合理。(A)「搭計程車吧，比較舒服」與塞車的理由矛盾；(B)「演唱會八點開始」、(C)「我從來沒去過演唱會」都沒有回答要選哪種交通工具。故選 (D)。", "level": "B1", "topic": "making plans"}, {"id": "M283", "type": "dialogue", "q": "A: Hi, Linda. This is Ben. ______ I have a high fever.\nB: Oh, I'm sorry to hear that. Take the day off and get some rest.", "options": ["I'm afraid I can't come to work today.", "I'll be there in ten minutes.", "Can I work overtime tonight?", "I just got a promotion."], "answer": 0, "explain": "Ben 打電話給主管 Linda 說自己發高燒；主管回答「那就請一天假，好好休息」，可知 Ben 是在請病假。(A)「恐怕我今天沒辦法去上班」最恰當。(B)「我十分鐘後到」、(C)「我今晚可以加班嗎？」都與發燒、需要休息矛盾；(D)「我剛升職了」是好消息，主管不會回應「聽到這消息很遺憾」。故選 (A)。", "level": "B2", "topic": "sick leave"}, {"id": "M284", "type": "dialogue", "q": "A: Customer service. How can I help you?\nB: I ordered a phone case two weeks ago, but it still hasn't arrived.\nA: ______\nB: Sure. It's 58302.", "options": ["Would you like to cancel your membership?", "What color would you like?", "Could you give me your order number, please?", "It will be delivered tomorrow."], "answer": 2, "explain": "B 向客服反映兩週前訂的手機殼還沒送到；B 接著回答「好的，是 58302」，可知客服要求提供一組號碼。(C)「可以給我您的訂單編號嗎？」最合理。(A)「您要取消會員資格嗎？」答非所問；(B)「您想要什麼顏色？」無法用號碼回答；(D)「明天會送達」是陳述句，B 不會接著說「好的，是 58302」。故選 (C)。", "level": "B2", "topic": "customer service"}, {"id": "M285", "type": "dialogue", "q": "A: Hi, I'm Amy. I just started working in the sales department.\nB: ______ I'm Tom from marketing. Let me know if you need anything.", "options": ["See you later.", "Sorry, I'm busy right now.", "Long time no see.", "Nice to meet you, Amy."], "answer": 3, "explain": "新同事 Amy 自我介紹；B 接著介紹自己是行銷部的 Tom，並說有需要可以找他，可知兩人是初次見面。(D)「很高興認識你，Amy」最恰當。(A)「待會見」是道別用語；(B)「抱歉，我現在很忙」與後面熱心提供協助矛盾；(C)「好久不見」用於久別重逢的熟人，不適用於初次見面。故選 (D)。", "level": "B1", "topic": "introductions"}, {"id": "M286", "type": "dialogue", "q": "A: Oh no, I left my wallet at home. ______\nB: Sure. How much do you need?", "options": ["Can you pay me back tomorrow?", "Could you lend me some money for lunch?", "Did you find my wallet?", "How much is your wallet?"], "answer": 1, "explain": "A 發現錢包忘在家裡；B 回答「當然，你需要多少？」，可知 A 想跟 B 借錢。(B)「可以借我一點錢買午餐嗎？」最合理。(A)「你明天能還我錢嗎？」是借錢給別人的人說的，A 並沒有借錢給 B；(C)「你找到我的錢包了嗎？」A 已經知道錢包在家裡；(D)「你的錢包多少錢？」答非所問。故選 (B)。", "level": "B1", "topic": "borrowing"}, {"id": "M287", "type": "dialogue", "q": "A: It's a bit chilly in here. ______\nB: Not at all. I was feeling cold, too.", "options": ["Would you like me to open the window?", "Can you turn on the fan?", "Would you mind if I closed the window?", "Do you feel like going swimming?"], "answer": 2, "explain": "A 覺得有點冷；B 回答「一點也不（介意），我也覺得冷」，Not at all 是回答 Would you mind...? 表示同意的典型說法。(C)「你介意我把窗戶關上嗎？」最恰當。(A)「要我幫你開窗嗎？」與覺得冷矛盾，且不能用 Not at all 回答；(B)「你可以打開電風扇嗎？」會更冷，也不能用 Not at all 回答；(D)「你想去游泳嗎？」與情境無關。故選 (C)。", "level": "B2", "topic": "polite requests"}, {"id": "M288", "type": "dialogue", "q": "A: Ms. Lee, I don't quite understand this grammar rule. ______\nB: Of course. Come to my office after class.", "options": ["Could you explain it to me again?", "Could you give us less homework?", "Why do we have to learn grammar?", "May I go to the restroom?"], "answer": 0, "explain": "學生說不太懂這條文法規則；老師回答「當然，下課後來我辦公室」，可知學生請老師再講解一次。(A)「您可以再跟我解釋一次嗎？」最合理。(B)「可以少出一點作業嗎？」與不懂文法無關，老師也不會為此請學生下課到辦公室；(C)「我們為什麼要學文法？」不能用 Of course 回答；(D)「我可以去洗手間嗎？」與「下課後來辦公室」不連貫。故選 (A)。", "level": "B1", "topic": "school"}, {"id": "M289", "type": "dialogue", "q": "A: How would you like your eggs?\nB: ______\nA: OK. And would you like toast with that?", "options": ["Very much, thank you.", "Scrambled, please.", "Two dozen, please.", "They're delicious."], "answer": 1, "explain": "「How would you like your eggs?」是問「蛋要怎麼料理？」，應回答烹調方式。(B)「請做炒蛋」最恰當。(A)「非常喜歡，謝謝」誤把 How would you like 當成「喜不喜歡」；(C)「請給我兩打」回答數量，一打（dozen）是十二個，不合點餐情境；(D)「很好吃」表示已經吃過，但此時才剛要點餐。故選 (B)。", "level": "B1", "topic": "restaurant"}, {"id": "M290", "type": "dialogue", "q": "A: Good morning, Star Electronics.\nB: Hi. I'm calling about the job opening I saw on your website.\nA: ______\nB: Sure, I'll wait.", "options": ["You can call me any time.", "What would you like to buy?", "Sorry, I didn't apply for it.", "Please hold. I'll transfer you to Human Resources."], "answer": 3, "explain": "B 打電話詢問公司網站上的職缺；B 接著說「好，我等」，可知對方請他稍候。(D)「請稍候，我幫您轉接人資部」最合理，transfer 在電話中指「轉接」。(A)「你隨時可以打給我」不會接「我等」；(B)「您想買什麼？」答非所問；(C)「抱歉，我沒有應徵」說話者錯誤，要應徵的是 B 而不是接電話的人。故選 (D)。", "level": "B2", "topic": "phone call"}, {"id": "M291", "type": "dialogue", "q": "A: Would you like some more noodles?\nB: ______ I'm full. Everything was delicious, though.\nA: I'm glad you enjoyed it.", "options": ["No, thanks.", "Yes, please.", "Help yourself.", "Here you are."], "answer": 0, "explain": "主人問 B 要不要再來些麵；B 接著說「我飽了，不過每道菜都很好吃」，可知 B 婉拒。(A)「不用了，謝謝」最恰當。(B)「好，麻煩了」與吃飽矛盾；(C)「請自便」是主人招待客人的用語；(D)「給你」是遞東西時說的話，不是回答詢問。故選 (A)。", "level": "B1", "topic": "dining"}, {"id": "M292", "type": "dialogue", "q": "A: Bright Smile Dental Clinic. How may I help you?\nB: ______\nA: Let me check. Is Wednesday at 4 p.m. OK for you?", "options": ["I'd like to cancel my order.", "My teeth look great, thanks.", "I'd like to make an appointment for a checkup.", "Could you tell me how to brush my teeth?"], "answer": 2, "explain": "B 打電話到牙醫診所；對方接著說「我查一下，週三下午四點可以嗎？」，可知 B 想預約看診。(C)「我想預約做檢查」最合理。(A)「我想取消訂單」是購物用語；(B)「我的牙齒看起來很好，謝謝」不需要安排時間；(D)「你可以告訴我怎麼刷牙嗎？」與安排看診時段無關。故選 (C)。", "level": "B1", "topic": "health"}, {"id": "M293", "type": "dialogue", "q": "A: I think we should do our project on plastic pollution.\nB: ______ Many groups have already chosen that topic. How about light pollution?", "options": ["I totally agree with you.", "I'm not sure that's a good idea.", "That's exactly what I was going to say.", "Let's do it right now."], "answer": 1, "explain": "A 提議報告主題做塑膠污染；B 接著說很多組已經選了這個題目，並改提光害，可知 B 不贊成。(B)「我不確定那是個好主意」是委婉表達反對的說法。(A)「我完全同意你」、(C)「我正要這麼說」、(D)「我們現在就開始吧」都表示贊成，與後面另提新主題矛盾。故選 (B)。", "level": "B2", "topic": "group project"}, {"id": "M294", "type": "dialogue", "q": "A: Excuse me. Where can I find the olive oil?\nB: ______\nA: Thank you. And where's the checkout counter?", "options": ["It's 250 dollars a bottle.", "We have it in two sizes.", "Sorry, we're closed tomorrow.", "It's in aisle 5, next to the vinegar."], "answer": 3, "explain": "A 在超市詢問橄欖油放在哪裡，應回答位置；A 接著道謝，並用 And where...? 再問另一個地點。(D)「在第五走道，醋的旁邊」（aisle 走道）最合理。(A)「一瓶 250 元」回答價格；(B)「我們有兩種容量」回答尺寸；(C)「抱歉，我們明天公休」與詢問位置無關。故選 (D)。", "level": "B1", "topic": "supermarket"}, {"id": "M295", "type": "dialogue", "q": "A: My suitcase didn't come out on the baggage carousel.\nB: I'm sorry to hear that. ______\nA: It's a large black one with a red ribbon on the handle.", "options": ["Where are you flying to next?", "How much did you pay for it?", "Could you describe it for me?", "Did you pack it yourself?"], "answer": 2, "explain": "A 在機場行李轉盤等不到自己的行李箱；A 接著描述「是一個大型黑色行李箱，提把上綁著紅色緞帶」，可知機場人員請 A 描述外觀。(C)「可以描述一下它的樣子嗎？」最合理。(A)「你接下來要飛去哪？」應回答地點；(B)「你買它花了多少錢？」應回答價格；(D)「是你自己打包的嗎？」應回答 Yes/No。故選 (C)。", "level": "B2", "topic": "airport"}, {"id": "M296", "type": "dialogue", "q": "A: Did you get a chance to read my draft? What do you think?\nB: ______ But you might want to shorten the introduction a little.", "options": ["Overall, it looks good.", "I haven't read it yet.", "I wrote it myself.", "It's none of your business."], "answer": 0, "explain": "A 問 B 讀了自己的草稿沒有、覺得如何；B 接著說「不過你也許可以把引言縮短一點」，But 表示語氣轉折，前面應是正面評價。(A)「整體來說看起來不錯」最恰當。(B)「我還沒讀」與後面給出具體建議矛盾；(C)「是我自己寫的」不合理，草稿是 A 寫的；(D)「不關你的事」語氣無禮又不合邏輯。故選 (A)。", "level": "B2", "topic": "giving feedback"}, {"id": "M297", "type": "dialogue", "q": "A: I'd like to return these books, please.\nB: Let me see... ______\nA: Oh, really? How much is the fine?", "options": ["You can borrow up to five books.", "This one is three days overdue.", "Thanks for returning them early.", "The library closes at nine."], "answer": 1, "explain": "A 在圖書館還書；A 接著問「罰款多少？」，可知館員指出書逾期了。(B)「這本逾期三天了」最合理，overdue 意為「過期的、逾期的」。(A)「你最多可以借五本」與罰款無關；(C)「謝謝你提早歸還」提早還書不會被罰款；(D)「圖書館九點關門」與罰款無關。故選 (B)。", "level": "B2", "topic": "library"}, {"id": "M298", "type": "dialogue", "q": "A: Does this salad have any nuts in it? ______\nB: I'm not sure. Let me check with the kitchen. We don't want you to get sick.", "options": ["I'd like extra nuts, please.", "It tastes a little salty.", "I'm a vegetarian, so I don't eat meat.", "I'm allergic to them."], "answer": 3, "explain": "A 問沙拉裡有沒有堅果；服務生說要去廚房確認，並說「我們不希望您身體不舒服」，可知 A 對堅果過敏。(D)「我對堅果過敏」最合理，them 指 nuts。(A)「我想多加一些堅果」與擔心生病無關；(B)「吃起來有點鹹」表示已經吃過，與詢問成分及後文不符；(C)「我吃素，所以不吃肉」與堅果無關。故選 (D)。", "level": "B2", "topic": "food allergy"}, {"id": "M299", "type": "dialogue", "q": "A: Hello. Could I speak to Mr. Huang, please?\nB: ______\nA: This is Jenny Wu from Green Bank.", "options": ["May I ask who's calling?", "Sorry, I'm busy right now.", "Yes, I'll call you back.", "You're welcome."], "answer": 0, "explain": "A 打電話找黃先生；A 接著說「我是綠色銀行的吳珍妮」，可知接電話的人詢問來電者的身分。(A)「請問您是哪位？」最合理。(B)「抱歉，我現在很忙」、(C)「好，我再回電給你」都不會讓 A 接著自我介紹；(D)「不客氣」用於回應道謝，A 並沒有道謝。故選 (A)。", "level": "B1", "topic": "phone call"}, {"id": "M300", "type": "dialogue", "q": "A: The final exams are coming up. Do you want to study together this Saturday?\nB: ______ What time shall we meet?\nA: How about nine in the morning at the city library?", "options": ["Sorry, I have to work all weekend.", "I'd rather study alone.", "That's a great idea.", "The exams were easier than I expected."], "answer": 2, "explain": "A 約 B 週六一起準備期末考；B 接著問「我們幾點見面？」，可知 B 同意。(C)「好主意」最恰當。(A)「抱歉，我整個週末都要打工」、(B)「我寧願自己讀」都表示拒絕，與接著約時間矛盾；(D)「考試比我預期的簡單」表示已經考完，與「期末考快到了」矛盾。故選 (C)。", "level": "B1", "topic": "making plans"}];
